import type { BChap } from '../types';
const C: BChap[] = [{"v":["Після смерти Саула, коли Давид повернувся після поразки амаликитян і пробув у Секелагу два дні,","ось, на третій день приходить чоловік зі стану Саулового; одяг на ньому розідраний і порох на голові його. Прийшовши до Давида, він упав на землю і поклонився [йому].","І сказав йому Давид: звідки ти прийшов? І сказав той: я втік зі стану ізраїльського.","І сказав йому Давид: що відбулося? розкажи мені. І той сказав: народ побіг з битви, і безліч народу впало і померло, і вмерли і Саул і син його Іонафан.","І сказав Давид отрокові, який розповідав йому: як ти знаєш, що Саул і син його Іонафан померли?","І сказав отрок, який розповідав йому: я випадково прийшов на гору Гелвуйську, і ось, Саул упав на свій спис, колісниці ж і вершники наздоганяли його.","Тоді він оглянувся назад і, побачивши мене, покликав мене.","І я сказав: ось я. Він сказав мені: хто ти? І я сказав йому: я — амаликитянин.","Тоді він сказав мені: підійди до мене й убий мене, бо туга смертна охопила мене, душа моя усе ще в мені.","І я підійшов до нього й убив його, бо знав, що він не буде живий після свого падіння; і взяв я [царський] вінець, який був на голові його, і зап’ястя, яке було на руці його, і приніс їх до господаря мого сюди.","Тоді схопив Давид одяг свій і роздер його, також і всі люди, які були з ним, [роздерли одяг свій,]","і ридали і плакали, і постилися до вечора за Саула і за сина його Іонафана, і за народ Господній і за дім Ізраїлів, що впали вони від меча.","І сказав Давид отроку, який розповідав йому: звідки ти? І сказав він: я — син прибульця амаликитянина.","Тоді Давид сказав йому: як не побоявся ти підняти руку, щоб убити помазаника Господнього?","І покликав Давид одного зі слуг і сказав йому: підійди, убий його.","І той убив його, і він помер. І сказав до нього Давид: кров твоя на голові твоїй, бо твої вуста свідчили проти тебе, коли ти говорив: я убив помазаника Господнього.","І оплакав Давид Саула і сина його Іонафана цією плачевною піснею,","і повелів навчити синів Іудиних луку, як написано в книзі Праведного, і сказав:","краса твоя, о Ізраїлю, вражена на висотах твоїх! як упали сильні!","Не розповідайте в Гефі, не сповіщайте на вулицях Аскалона, щоб не раділи дочки филистимлян, щоб не торжествували дочки необрізаних.","Гори Гелвуйські! нехай [не зійде] ні роса, ні дощ на вас, і нехай не буде на вас полів з плодами, бо там уражений щит сильних, щит Саула, ніби не був він помазаний єлеєм.","Без крови поранених, без жиру сильних лук Іонафана не повертався назад, і меч Саула не повертався марно.","Саул та Іонафан, люб’язні і злагідні в житті своєму, не розлучилися й у смерті своїй; швидші за орлів, сильніші за левів вони були.","Дочки ізраїльські! плачте за Саулом, який одягав вас у багряницю з прикрасами і діставав на одяг ваш золоті прикраси.","Як упали сильні на полі битви! Убитий Іонафан на висотах твоїх.","Тужу за тобою, брате мій Іонафане; ти був дуже дорогим для мене; любов твоя була для мене вище за любов жіночу.","Як упали сильні, загинула зброя військова!"],"x":{"1":"8.27.6","2":"0.37.34|8.4.12|24.2.12","4":"9.4.10","11":"8.4.12|9.3.31","14":"8.10.1|25.104.15","15":"9.4.10:12","18":"0.49.8|5.10.13","20":"8.17.23|6.11.34|6.14.19","21":"8.31.1","22":"8.14.6","26":"9.9.1|8.18.1"}},{"v":["Після цього Давид запитав Господа, говорячи: чи йти мені в яке-небудь місто Іудине? І сказав йому Господь: іди. І сказав Давид: куди йти? І сказав Він: у Хеврон.","І пішов туди Давид і обидві дружини його, Ахиноама ізреелитянка й Авигея, колишня дружина Навала, кармилитянка.","І людей, які були з ним, привів Давид, кожного з родиною його, й оселилися в місті Хевроні.","І прийшли мужі Іудині і помазали там Давида на царство над домом Іудиним. І донесли Давиду, що жителі Іависа галаадського поховали Саула.","І відправив Давид послів до жителів Іависа галаадського, сказати їм: благословенні ви у Господа за те, що зробили цю милість господареві своєму Саулу, [помазаникові Господньому,] і поховали його [та Іонафана, сина його],","і нині нехай віддасть вам Господь милістю й істиною; і я зроблю вам благодіяння за те, що ви це зробили;","нині нехай зміцняться руки ваші, і будьте мужні; бо господар ваш Саул помер, а мене помазав дім Іудин царем над собою.","Але Авенир, син Нирів, начальник війська Саулового, взяв Ієвосфея, сина Саулового, і привів його в Маханаїм,","і поставив його царем над Галаадом, і Ашуром, і Ізреелем, і Єфремом, і Веніаміном, і над усім Ізраїлем.","Сорок років було Ієвосфею, синові Сауловому, коли він став царем над Ізраїлем, і царював два роки. Тільки дім Іудин залишився з Давидом.","Всього часу, в який Давид царював у Хевроні над домом Іудиним, було сім років і шість місяців.","І вийшов Авенир, син Нирів, і слуги Ієвосфея, сина Саулового, з Маханаїма в Гаваон.","Вийшов і Іоав, син Саруї, зі слугами Давида, і зустрілися біля Гаваонського ставу, і засіли ті на одній стороні ставу, а ці на іншій стороні ставу.","І сказав Авенир Іоаву: нехай встануть юнаки і пограють перед нами. І сказав Іоав: нехай встануть.","І встали і пішли кількістю дванадцять веніамитян з боку Ієвосфея, сина Саулового, і дванадцять зі слуг Давидових.","Вони схопили один одного за голову, встромили меч один одному в бік і упали разом. І було названо це місце Хелкаф-Хаццурим, що в Гаваоні.","І відбулася в той день найжорстокіша битва, і Авенир з людьми ізраїльськими був уражений слугами Давида.","І були там три сини Саруї: Іоав, і Авесса, й Асаїл. Асаїл же був легкий на ноги, як сарна в полі.","І погнався Асаїл за Авениром і переслідував його, не ухиляючись ні праворуч, ні ліворуч від слідів Авенира.","І оглянувся Авенир назад і сказав: чи ти це, Асаїл? Той сказав: я.","І сказав йому Авенир: ухилися праворуч або ліворуч, і вибери собі одного зі слуг і візьми собі його озброєння. Але Асаїл не захотів відстати від нього.","І повторив Авенир ще, говорячи Асаїлу: відстань від мене, щоб я не повалив тебе на землю; тоді з яким лицем з’явлюся я до Іоава, брата твого?","[і де це буває? повернися до брата твого Іоава.] Але той не захотів відстати. Тоді Авенир, повернувши спис, уразив його в живіт; спис пройшов наскрізь його, і він упав там же і помер на місці. Усі, проходячи через те місце, де упав і помер Асаїл, зупинялися.","І переслідували Іоав і Авесса Авенира. Сонце вже зайшло, коли вони прийшли до пагорба Амма, що проти Гиаха, на дорозі до пустелі Гаваонської.","І зібралися веніамитяни навколо Авенира і склали одне ополчення, і стали на вершині одного пагорба.","І звернувся Авенир до Іоава, і сказав: чи вічно буде пожирати меч? Чи ти не знаєш, що наслідки будуть сумні? І доки ти не скажеш людям, щоб вони перестали переслідувати братів своїх?","І сказав Іоав: живий Бог! якби ти не говорив інше, то ще ранком перестали б люди переслідувати братів своїх.","І засурмив Іоав трубою, і зупинився весь народ, і не переслідували більше ізраїльтян; битва припинилася.","Авенир же і люди його йшли рівниною всю ту ніч і перейшли Йордан, і пройшли весь Битрон, і прийшли в Маханаїм.","І повернувся Іоав від переслідування Авенира і зібрав весь народ, і бракувало зі слуг Давидових дев’ятнадцять чоловік, крім Асаїла.","Слуги ж Давидові вразили веніамитян і людей Авенирових; упало їх триста шістдесят чоловік.","І взяли Асаїла і поховали його в гробі батька його, що у Вифлеємі. Іоав же з людьми своїми йшов усю ніч і на світанку прибув у Хеврон."],"x":{"1":"8.23.2","2":"8.25.42","4":"8.31.11|21.2.57","5":"8.15.13","8":"8.14.50","9":"3.32.40|5.19.18","11":"9.5.5","12":"5.9.3|5.21.17","13":"32.41.12","18":"12.2.16","23":"9.3.27","28":"9.18.16"}},{"v":["І був довгочасний розбрат між домом Сауловим і домом Давидовим. Давид все більше і більше дужчав, а дім Саулів більше і більше слабшав.","І народилися у Давида [шість] синів у Хевроні. Первісток його був Амнон від Ахиноами ізреелитянки,","а другий [син] його — Далуя від Авигеї, колишньої дружини Навала, кармилитянки; третій — Авессалом, син Маахи, дочки Фалмая, царя Гессурського;","четвертий — Адонія, син Аггифи; п’ятий — Сафатія, син Авитали;","шостий — Ієфераам від Егли, дружини Давидової. Вони народилися у Давида у Хевроні.","Коли був розбрат між домом Саула і домом Давида, то Авенир підтримував дім Саула.","У Саула була наложниця, на ім’я Рицпа, дочка Айя [і ввійшов до неї Авенир]. І сказав [Ієвосфей] Авениру: навіщо ти ввійшов до наложниці батька мого?","Авенир же сильно розгнівався на слова Ієвосфея і сказав: хіба я — собача голова? Я проти Іуди зробив нині милість дому Саула, батька твого, братам його і друзям його, і не видав тебе в руки Давида, а ти звинувачуєш нині мене у гріху через жінку.","Те і те нехай зробить Бог Авениру і ще більше зробить йому! Як клявся Господь Давиду, так і зроблю йому [в цей день]:","відніму царство від дома Саулового і поставлю престіл Давида над Ізраїлем і над Іудою, від Дана до Вирсавії.","І не міг Ієвосфей заперечити Авениру, бо боявся його.","І послав Авенир від себе послів до Давида [у Хеврон, де він знаходився], сказати: чия ця земля? І ще сказати: уклади союз зі мною, і рука моя буде з тобою, щоб навернути до тебе весь народ ізраїльський.","І сказав [Давид]: добре, я укладу союз з тобою, тільки прошу тебе про одне, а саме — ти не побачиш лиця мого, якщо не приведеш із собою Мелхоли, дочки Саула, коли прийдеш побачитися зі мною.","І відправив Давид послів до Ієвосфея, сина Саулового, сказати: віддай дружину мою Мелхолу, яку я одержав за сто краєобрізань филистимських.","І послав Ієвосфей і взяв її від чоловіка, від Фалтія, сина Лаїшевого.","Пішов з нею і чоловік її і з плачем проводжав її до Бахурима; але Авенир сказав йому: йди назад. І він повернувся.","І звернувся Авенир до старійшин ізраїльських, говорячи: і вчора і третього дня ви бажали, щоб Давид був царем над вами,","тепер зробіть це, бо Господь сказав Давиду: «рукою раба Мого Давида Я спасу народ Мій Ізраїля від руки филистимлян і від руки усіх ворогів його».","Те саме говорив Авенир і веніамитянам. І пішов Авенир у Хеврон, щоб переказати Давиду все, чого бажав Ізраїль і весь дім Веніамінів.","І прийшов Авенир до Давида в Хеврон і з ним двадцять чоловік, і зробив Давид бенкет для Авенира і людей, які були з ним.","І сказав Авенир Давиду: я встану і піду і зберу до господаря мого царя весь народ ізраїльський, і вони вступлять у завіт з тобою, і будеш царювати над усіма, як бажає душа твоя. І відпустив Давид Авенира, і він пішов з миром.","І ось, слуги Давидові з Іоавом прийшли з походу і принесли із собою багато здобичі; але Авенира вже не було з Давидом у Хевроні, бо Давид відпустив його, і він пішов з миром.","Коли Іоав і усе військо, що ходило з ним, прийшли, то Іоаву розповіли: приходив Авенир, син Нирів, до царя, і той відпустив його, і він пішов з миром.","І прийшов Іоав до царя і сказав: що ти зробив? Ось, приходив до тебе Авенир; навіщо ти відпустив його, і він пішов?","Ти знаєш Авенира, сина Нирового: він приходив обманути тебе, довідатися про вихід твій і вхід твій і розвідати все, що ти робиш.","І вийшов Іоав від Давида і послав гінців слідом за Авениром; і повернули вони його від колодязя Сиру, без відома Давида.","Коли Авенир повернувся в Хеврон, то Іоав відвів його усередину воріт, начебто для того, щоб поговорити з ним таємно, і там уразив його в живіт. І помер Авенир за кров Асаїла, брата Іоавового.","І почув опісля Давид про це і сказав: невинний я і царство моє повік перед Господом у крові Авенира, сина Нирового;","нехай упаде вона на голову Іоава і на весь дім батька його; нехай ніколи не залишається дім Іоава без сіменеточивого, або прокаженого, або того, хто спирається на посох, або того, хто падає від меча, або того, хто потребує хліба.","Іоав же і брат його Авесса убили Авенира за те, що він умертвив брата їхнього Асаїла в битві біля Гаваона.","І сказав Давид Іоаву і всім людям, які були з ним: роздеріть одяг ваш й одягніться у волосяницю і плачте над Авениром. І цар Давид ішов за гробом його.","Коли погребали Авенира в Хевроні, то цар голосно плакав над гробом Авенира; плакав і весь народ.","І оплакав цар Авенира, говорячи: чи смертю підлого помирати Авениру?","Руки твої не були зв’язані, і ноги твої не в кайданах, і ти упав, як падають від розбійників. І весь народ став ще більше плакати над ним.","І прийшов весь народ запропонувати Давиду хліба, коли ще тривав день; але Давид поклявся, говорячи: те і те нехай зробить зі мною Бог і ще більше зробить, якщо я до заходу сонця споживу хліба або чого-небудь.","І весь народ довідався про це, і сподобалося йому це, як і все, що робив цар, подобалося всьому народові.","І дізнався весь народ і весь Ізраїль у той день, що не від царя сталося умертвлення Авенира, сина Нирового.","І сказав цар слугам своїм: чи знаєте, що вождь і великий муж упав у цей день в Ізраїлі?","Я тепер ще слабкий, хоча і помазаний на царство, а ці люди, сини Саруї, сильніші за мене; нехай же віддасть Господь тому, хто чинить зле, за злобою його!"],"x":{"1":"9.5.10","2":"12.3.1","3":"12.3.1-2","4":"10.1.5","5":"12.3.3","7":"9.21.8","8":"8.24.15|9.9.8","10":"6.20.1|8.3.20|9.17.11","14":"8.18.27","15":"8.25.44","18":"9.5.2","19":"12.12.29","22":"9.4.1","25":"9.10.3","27":"9.2.23|10.2.5:32","29":"10.2.33|2.15.2|11.5.27","30":"9.2.23|10.2.5","31":"39.2.13","35":"9.19.13","38":"8.26.15","39":"25.61.13|10.2.32"}},{"v":["І почув [Ієвосфей,] син Саулів, що помер Авенир у Хевроні, й опустилися руки його, і весь Ізраїль збентежився.","У [Ієвосфея,] сина Саулового, два було начальники війська; ім’я одного — Баана й ім’я другого — Рихав, сини Реммона беерофянина, з нащадків Веніамінових, бо і Беероф зараховувався до Веніаміна.","І втекли беерофяни в Гиффаїм і залишилися там прибульцями до цього дня.","В Іонафана, сина Саулового, був син кульгавий. П’ять років було йому, коли прийшла звістка про Саула та Іонафана з Ізрееля, і нянька, узявши його, побігла. І коли вона бігла поспішно, то він упав, і зробився кульгавим. Ім’я його Мемфивосфей.","І пішли сини Реммона беерофянина, Рихав і Баана, і прийшли в саму спеку дня до дому Ієвосфея; а він спав на постілі опівдні.","[А воротар дому, який очищав пшеницю, задрімав і заснув] і Рихав і Баана, брат його, ввійшли усередину дому, ніби для того, щоб узяти пшениці; і вразили його в живіт і утекли.","Коли вони ввійшли в дім, [Ієвосфей] лежав на постілі своїй, у спальній кімнаті своїй; і вони вразили його, і умертвили його, і відрубали голову його, і взяли голову його із собою, і йшли безлюдною дорогою всю ніч;","і принесли голову Ієвосфея до Давида в Хеврон і сказали цареві: ось голова Ієвосфея, сина Саула, ворога твого, який шукав душі твоєї; нині Господь помстився за господаря мого царю Саулу, [ворогові твоєму] і нащадкам його.","І відповів Давид Рихаву і Баані, братові його, синам Реммона беерофянина, і сказав їм: живий Господь, Який визволив душу мою від усякої скорботи!","якщо того, хто приніс мені звістку, сказавши: «ось, помер Саул, [та Іонафан]», і хто вважав себе радісним вісником, я схопив і убив його в Секелагу, замість того, щоб дати йому нагороду,","то тепер, коли негідні люди убили людину невинну в її домі на постелі її, невже я не стягну крови його від руки вашої і не знищу вас із землі?","І наказав Давид слугам, і вбили їх, і відрубали їм руки і ноги, і повісили їх над ставом у Хевроні. А голову Ієвосфея взяли і поховали в гробі Авенира, у Хевроні."],"x":{"1":"31.13.7|32.50.43","2":"5.18.25","3":"8.31.7","4":"9.9.3|8.29.11|12.9.40","5":"9.2.8","9":"0.48.16","10":"9.1.4","12":"9.1.15"}},{"v":["І прийшли всі коліна Ізраїлеві до Давида в Хеврон і сказали: ось, ми — кості твої і плоть твоя;","ще вчора і третього дня, коли Саул царював над нами, ти виводив і вводив Ізраїля; і сказав Господь тобі: «ти будеш пасти народ Мій Ізраїля і ти будеш вождем Ізраїля».","І прийшли усі старійшини Ізраїля до царя в Хеврон, і уклав з ними цар Давид завіт у Хевроні перед Господом; і помазали Давида на царя над [усім] Ізраїлем.","Тридцять років було Давиду, коли він став царем; царював сорок років.","У Хевроні царював над Іудою сім років і шість місяців, і в Єрусалимі царював тридцять три роки над усім Ізраїлем та Іудою.","І пішов цар і люди його на Єрусалим проти ієвусеїв, жителів тієї країни; але вони говорили Давиду: «ти не ввійдеш сюди; тебе відженуть сліпі й кульгаві», — це значило: «не ввійде сюди Давид».","Але Давид узяв фортецю Сион: це — місто Давидове.","І сказав Давид у той день: усякий, убиваючи ієвусеїв, нехай уражує списом і кульгавих і сліпих, які ненавидять душу Давида. Тому і говориться: сліпий і кульгавий не ввійде в дім [Господній].","І оселився Давид у фортеці, і назвав її містом Давидовим, і оббудував навкруги від Милло й усередині.","І процвітав Давид і підносився, і Господь Бог Саваоф був з ним.","І прислав Хирам, цар Тирський, послів до Давида і кедрові дерева, і теслярів і каменярів, і вони побудували дім Давиду.","І зрозумів Давид, що Господь утвердив його царем над Ізраїлем і що підніс царство його заради народу Свого Ізраїля.","І взяв Давид ще наложниць і дружин з Єрусалима, після того, як прийшов з Хеврона.","І народилися ще в Давида сини і дочки. І ось імена народжених у нього в Єрусалимі: Самус, і Совав, і Нафан, і Соломон,","і Евеар, і Елисуа, і Нафек, і Іафія,","і Елисама, і Елидає, і Елифалеф, [Самає, Іосиваф, Нафан, Галамаан, Ієваар, Феїсус, Елифалаф, Нагев, Нафек, Іонафан, Леасамис, Ваалимаф і Елифааф].","Коли филистимляни почули, що Давида помазали на царство над Ізраїлем, то піднялися усі филистимляни шукати Давида. І почув Давид і пішов у фортецю.","А филистимляни прийшли і розташувалися в долині Рефаїм.","І запитав Давид Господа, говорячи: чи йти мені проти филистимлян? чи віддаси їх у руки мої? І сказав Господь Давиду: йди, бо Я видам филистимлян у руки твої.","І пішов Давид у Ваал-Перацим і вразив їх там, і сказав Давид: Господь розніс ворогів моїх переді мною, як розносить вода. Тому і місцю тому дано ім’я Ваал-Перацим.","І залишили там [филистимляни] ідолів своїх, а Давид з людьми своїми взяв їх [і повелів спалити їх у вогні].","І прийшли знову филистимляни і розташувалися в долині Рефаїм.","І запитав Давид Господа, [чи йти мені проти филистимлян, і чи віддаси їх у руки мої?] І Він відповів йому: не виходь назустріч їм, а зайди їм з тилу і йди до них з боку шовковичного гаю;","і коли почуєш шум, ніби хтось іде по вершинах шовковичних дерев, то рушай, бо тоді пішов Господь перед тобою, щоб уразити військо филистимське.","І зробив Давид, як повелів йому Господь, і вразив филистимлян від Гаваї до Газера."],"x":{"1":"12.11.1","2":"8.18.16","3":"12.11.3","4":"10.2.11","5":"9.2.11","6":"12.11.4|6.19.10|5.15.63","7":"10.2.10","8":"5.15.63|12.11.6","9":"10.9.15|12.11.8","11":"12.14.1","12":"12.14.2|25.29.2","14":"12.3.5|52.3.31","16":"12.14.7","17":"12.14.8","18":"5.15.8","19":"8.23.2","20":"12.14.11|31.28.21","21":"8.31.9|4.7.5|12.14.12","24":"6.4.14","25":"6.19.13|12.14.16"}},{"v":["І зібрав знову Давид усіх добірних людей з Ізраїля, тридцять тисяч*.","І встав і пішов Давид і весь народ, який був з ним з Ваала Іудиного, щоб перенести звідти ковчег Божий, на якому нарікається ім’я Господа Саваофа, Який сидить на херувимах.","І поставили ковчег Божий на нову колісницю і вивезли його з дому Аминадава, що на пагорбі. Сини ж Аминадава, Оза й Ахио, вели нову колісницю.","І повезли її з ковчегом Божим з дому Аминадава, що на пагорбі; і Ахио йшов перед ковчегом [Господнім].","А Давид і всі сини Ізраїлеві грали перед Господом на різних музичних інструментах з кипарисового дерева, і на цитрах, і на псалтирях, і на тимпанах, і на систрах, і на кимвалах.","І коли дійшли до току Нахонового, Оза простяг руку свою до ковчега Божого [щоб притримати його] і взявся за нього, бо воли нахилили його.","Але Господь прогнівався на Озу, і вразив його Бог там же за завзятість, і помер він там біля ковчега Божого.","І засмутився Давид, що Господь уразив Озу. Місце це і донині називається: «ураження Ози».","І убоявся Давид у той день Господа і сказав: як увійти до мене ковчегу Господньому?","І не захотів Давид везти ковчег Господній до себе, в місто Давидове, а завернув його в дім Аведдара гефянина.","І залишався ковчег Господній у домі Аведдара гефянина три місяці, і благословив Господь Аведдара і весь дім його.","Коли донесли царю Давиду, говорячи: «Господь благословив дім Аведдара й усе, що було в нього, заради ковчега Божого», то пішов Давид і урочисто переніс ковчег Божий з дому Аведдара в місто Давидове.","І коли ті, що несли ковчег Господній, проходили по шість кроків, він приносив у жертву тельця й барана.","Давид скакав із усієї сили перед Господом; одягнений же був Давид у лляний ефод.","Так Давид і весь дім Ізраїлів несли ковчег Господній з вигуками і трубними звуками.","Коли входив ковчег Господній у місто Давидове, Мелхола, дочка Саула, дивилася у вікно і, побачивши царя Давида, що скакає і танцює перед Господом, принизила його в серці своєму.","І принесли ковчег Господній і поставили його на своєму місці посеред скинії, яку спорудив для нього Давид; і приніс Давид всепалення перед Господом і жертви мирні.","Коли Давид закінчив приношення всепалень і жертв мирних, то благословив він народ ім’ям Господа Саваофа;","і роздав усьому народові, усій безлічі ізраїльтян [від Дана навіть до Вирсавії], як чоловікам, так і жінкам, по одному хлібу і по шматку смаженого м’яса і по одному коржу кожному. І пішов весь народ, кожен у дім свій.","Коли Давид повернувся, щоб благословити дім свій, то Мелхола, дочка Саула, вийшла до нього назустріч, [і вітала його] і сказала: як відзначився сьогодні цар Ізраїлів, оголившись сьогодні перед очима рабинь рабів своїх, як оголюється яка-небудь пуста людина!","І сказав Давид Мелхолі: перед Господом [танцювати буду. І благословенний Господь], Який віддав перевагу мені перед батьком твоїм і всім домом його, утвердивши мене вождем народу Господнього, Ізраїля; перед Господом грати і танцювати буду;","і я ще більше принижусь, і зроблюся ще мізернішим в очах моїх, і перед служницями, про яких ти говориш, я буду славний.","І у Мелхоли, дочки Саулової, не було дітей до дня смерти її."],"x":{"1":"12.13.5","2":"1.25.20","3":"8.7.1","6":"12.13.9","7":"2.10.2","8":"12.13.11","9":"50.8.34|54.5.13","10":"12.13.13","11":"12.13.14","12":"12.13.14|9.5.7","14":"25.83.3","15":"12.15.28","16":"12.15.29|63.2.14","17":"12.16.1","18":"12.16.2|3.6.24","19":"12.16.3:43","21":"9.5.2","22":"25.83.11|25.130.1-2","23":"8.2.30|9.21.8"},"n":{"1":["У грецькому перекладі: близько сімдесяти тисяч"]}},{"v":["Коли цар жив у домі своєму, і Господь заспокоїв його від усіх навколишніх ворогів його,","тоді сказав цар пророку Нафану: ось, я живу в домі кедровому, а ковчег Божий знаходиться під наметом.","І сказав Нафан царю: усе, що в тебе на серці, йди, роби; бо Господь з тобою.","Але в ту ж ніч було слово Господа до Нафана:","йди, скажи рабові Моєму Давиду: так говорить Господь: чи ти побудуєш Мені дім для Мого перебування,","коли Я не жив у домі з того часу, як вивів синів Ізраїлевих з Єгипту, і до цього дня, але переходив у наметі й у скинії?","Де Я не ходив із усіма синами Ізраїля, чи говорив Я хоча слово якому-небудь з колін, якому Я призначив пасти народ Мій Ізраїля: «чому не побудуєте Мені кедрового дому»?","І тепер так скажи рабові Моєму Давиду: так говорить Господь Саваоф: Я взяв тебе від отари овець, щоб ти був вождем народу Мого, Ізраїля;","і був з тобою скрізь, куди не ходив ти, і знищив усіх ворогів твоїх перед лицем твоїм, і зробив ім’я твоє великим, як ім’я великих на землі.","І Я влаштую місце для народу Мого, для Ізраїля, й укоріню його, і буде він спокійно жити на місці своєму, і не буде тривожитися більше, і люди нечестиві не стануть більше тіснити його, як колись,","з того часу, як Я поставив суддів над народом Моїм, Ізраїлем; і Я заспокою тебе від усіх ворогів твоїх. І Господь сповіщає тобі, що Він влаштує тобі дім.","Коли ж сповняться дні твої, і ти спочинеш з батьками твоїми, то Я поставлю після тебе сíм’я твоє, яке народиться від стегон твоїх, і зміцню царство його.","Він побудує дім імені Моєму, і Я утверджу престіл царства його повіки.","Я буду йому батьком, і він буде Мені сином; і якщо він згрішить, Я покараю його жезлом мужів і ударами синів людських;","але милости Моєї не відніму від нього, як Я відняв від Саула, якого Я відкинув перед лицем твоїм.","І буде непохитний дім твій і царство твоє навіки перед лицем Моїм, і престіл твій устоїть повіки.","Усі ці слова і все це видіння Нафан переказав Давиду.","І пішов цар Давид, і став перед лицем Господа, і сказав: хто я, Господи [мій], Господи, і що таке дім мій, що Ти мене так звеличив!","І цього ще мало здалося в очах Твоїх, Господи мій, Господи; але Ти звістив ще про дім раба Твого в майбутньому. Це вже по-людськи. Господи мій, Господи!","Що ще може сказати Тобі Давид? Ти знаєш раба Твого, Господи мій, Господи!","Заради слова Твого і за серцем Твоїм Ти робиш це, відкриваючи все це велике рабові Твоєму.","В усьому великий Ти, Господи мій, Господи! бо немає подібного Тобі і немає Бога, крім Тебе, в усьому, що чули ми своїми вухами.","І хто подібний до народу Твого, Ізраїля, єдиного народу на Землі, заради якого приходив Бог, щоб придбати його Собі за народ і прославити Своє ім’я і звершити велике і страшне перед народом Твоїм, який Ти придбав Собі від єгиптян, вигнавши народи і богів їхніх?","І Ти укріпив за Собою народ Твій, Ізраїля, як власний народ, навіки, і Ти, Господи, зробився його Богом.","І нині, Господи Боже, утверди повіки слово, яке промовив Ти про раба Твого і про дім його, і виконай те, що Ти промовив.","І нехай звеличиться ім’я Твоє повіки, щоб говорили: «Господь Саваоф — Бог над Ізраїлем». І дім раба Твого Давида нехай буде міцним перед лицем Твоїм.","Оскільки ти, Господи Саваофе, Боже Ізраїлів, відкрив рабові Твоєму, говорячи: «влаштую тобі дім», то раб Твій уготував серце своє, щоб молитися Тобі такою молитвою.","Отже, Господи мій, Господи! Ти Бог, і слова Твої непорушні, і Ти звістив рабові Твоєму таке благо!","І нині почни і благослови дім раба Твого, щоб він був вічно перед лицем Твоїм, бо Ти, Господи мій, Господи, звістив це, і благословенням Твоїм стане дім раба Твого благословенним, [щоб бути йому перед Тобою] повіки."],"x":{"2":"12.17.1|54.7.46","3":"30.47.1","4":"12.17.3-4","5":"10.8.19","8":"8.16.11-12|25.77.70-71","10":"11.21.8|13.33.8","12":"10.8.20|13.21.7|25.131.11|54.2.30","13":"10.5.5","14":"11.8.19|12.17.13|25.88.33|75.1.5","15":"52.1.72|8.15.23","16":"10.11.38|25.88.37|53.12.34","17":"12.17.15","19":"12.17.17","20":"12.17.18|25.138.1-2|53.21.16","22":"25.85.10|31.44.6|31.45.21","23":"4.4.7|4.33.29|12.17.21|32.32.21","24":"0.17.7|32.31.33","27":"10.2.24","28":"12.17.26|52.1.38","29":"12.17.27"}},{"v":["Після цього Давид уразив филистимлян і упокорив їх, і взяв Давид Мефег-Гаамма з рук филистимлян.","І вразив моавитян і зміряв їх мотузкою, поклавши їх на землю; і відміряв дві мотузки на умертвлення, а одну мотузку на залишення в живих. І зробилися моавитяни у Давида рабами, які платять данину.","І вразив Давид Адраазара, сина Реховового, царя Сувського, коли той ішов, щоб відновити своє панування при ріці [Євфраті];","і взяв Давид у нього тисячу сімсот вершників* і двадцять тисяч чоловік піших, і підрізав Давид жили у всіх коней колісничних, залишивши [собі] з них для ста колісниць.","І прийшли сирійці дамаські на допомогу Адраазару, царю Сувському; але Давид уразив двадцять дві тисячі чоловік сирійців.","І поставив Давид охоронні війська в Сирії Дамаській, і стали сирійці у Давида рабами, які платять данину. І зберігав Господь Давида скрізь, куди тільки він ходив.","І взяв Давид золоті щити, що були у рабів Адраазара, і приніс їх в Єрусалим. [Їх узяв потім Сусаким, цар Єгипетський, під час навали своєї на Єрусалим, у дні Ровоама, сина Соломонового.]","А в Бефі і Берофі, містах Адраазарових, узяв цар Давид дуже багато міді, [з якої Соломон улаштував мідне море і стовпи, й умивальниці і всі сосуди].","І почув Фой, цар Імафа, що Давид уразив усе військо Адраазарове,","і послав Фой Іорама, сина свого, до царя Давида, вітати його і дякувати йому за те, що він воював з Адраазаром і вразив його; тому що Адраазар вів війни з Фоєм. У руках же Іорама були сосуди срібні, золоті й мідні.","Їх також присвятив цар Давид Господу, разом зі сріблом і золотом, яке присвятив із взятого у всіх підкорених ним народів:","у сирійців, і моавитян, і аммонитян, і филистимлян, і амаликитян, і з узятого у Адраазара, сина Реховового, царя Сувського.","І зробив Давид собі ім’я, повертаючись з ураження вісімнадцяти тисяч сирійців у долині Солоній.","І поставив він охоронні війська в Ідумеї; у всій Ідумеї поставив охоронні війська, і всі ідумеяни були рабами Давида. І зберігав Господь Давида скрізь, куди тільки він ходив.","І царював Давид над усім Ізраїлем, і чинив Давид суд і правду над усім народом своїм.","Іоав же, син Саруї, був начальником війська; й Іосафат, син Ахилуда, — діловодом;","Садок, син Ахитува, й Ахимелех, син Авиафара, — священиками, Сераія — писарем;","і Ванея, син Іодая, — начальником над хелефеями і фелефеями, і сини Давида — першими при дворі."],"x":{"1":"12.18.1","2":"3.22.3|12.18.2|4.2.9","3":"10.11.23","4":"9.10.18","5":"9.10.6","6":"12.18.6:13","7":"13.12.2","8":"12.18.8","9":"12.18.9","11":"12.18.11","13":"12.18.12","14":"12.18.13","15":"12.18.14","16":"9.20.23|12.18.15","17":"12.6.12","18":"9.15.18|10.1.38"},"n":{"4":["У грецькому перекладі: тисячу колісниць і сім тисяч вершників."]}},{"v":["І сказав Давид: чи не залишився ще хто-небудь з дому Саулового? я зробив би йому милість заради Іонафана.","В домі Саула був раб, на ім’я Сива; і покликали його до Давида, і сказав йому цар: чи ти Сива? І той сказав: я, раб твій.","І сказав цар: чи немає ще кого-небудь з дому Саулового? я зробив би йому милість Божу. І сказав Сива цареві: є син Іонафана, кульгавий на ноги.","І сказав йому цар: де він? І сказав Сива цареві: ось, він у домі Махира, сина Аммиелового, у Лодеварі.","І послав цар Давид, і взяли його з дому Махира, сина Аммиелового, з Лодевара.","І прийшов Мемфивосфей, син Іонафана, сина Саулового, до Давида, і упав на лице своє, і поклонився [цареві]. І сказав Давид: Мемфивосфею! І сказав той: ось раб твій.","І сказав йому Давид: не бійся; я зроблю тобі милість заради батька твого Іонафана і поверну тобі всі поля Саула, батька твого, і ти завжди будеш їсти хліб за моїм столом.","І поклонився [Мемфивосфей] і сказав: що таке раб твій, що ти зглянувся на такого мертвого пса, як я?","І покликав цар Сиву, слугу Саула, і сказав йому: усе, що належало Саулу і всьому дому його, я віддаю синові господаря твого;","отже, обробляй для нього землю ти і сини твої і раби твої, і доставляй плоди її, щоб у сина господаря твого був хліб для їжі; Мемфивосфей же, син господаря твого, завжди буде їсти за моїм столом. У Сиви було п’ятнадцять синів і двадцять рабів.","І сказав Сива цареві: усе, що наказує господар мій цар рабові своєму, виконає раб твій. Мемфивосфей їв за столом [Давида], як один із синів царя.","У Мемфивосфея був малолітній син, на ім’я Миха. Усі, хто жив у домі Сиви, були рабами Мемфивосфея.","І жив Мемфивосфей в Єрусалимі, тому що він їв завжди за царським столом. Він був кульгавий на обидві ноги."],"x":{"1":"12.19.2","2":"9.16.1","3":"8.20.14|9.4.4","4":"9.17.27","10":"9.16.3","11":"9.19.28","12":"12.8.34","13":"9.4.4"}},{"v":["Через деякий час помер цар Аммонитський, і запанував замість нього син його Аннон.","І сказав Давид: зроблю я милість Аннону, синові Наасовому, за благодіяння, які зробив мені батько його. І послав Давид слуг своїх утішити Аннона за батька його. І прийшли слуги Давидові в землю Аммонитську.","Але князі аммонитські сказали Аннону, господареві своєму: невже ти думаєш, що Давид з поваги до батька твого надіслав до тебе утішителів? чи не для того, щоб оглянути місто і виглядіти в ньому і потім зруйнувати його, надіслав Давид слуг своїх до тебе?","І взяв Аннон слуг Давидових, і поголив кожному з них половину бороди, і обрізав одяг їх наполовину, до стегон, й відпустив їх.","Коли донесли про це Давиду, то він послав до них назустріч, бо вони були дуже знечещені. І повелів цар сказати їм: залишайтеся в Єрихоні, поки відростуть бороди ваші, і тодіповернетеся.","І побачили аммонитяни, що вони зробилися ненависними для Давида; і послали аммонитяни найняти сирійців з Беф-Рехова і сирійців Суви двадцять тисяч піших, у царя [Амаликитського] Маахи тисячу чоловік і з Істова дванадцять тисяч чоловік.","Коли почув про це Давид, то послав Іоава з усім військом хоробрих.","І вийшли аммонитяни і розташувалися до битви біля воріт, а сирійці Суви і Рехова, й Істова, і Маахи, стали окремо в полі.","І побачив Іоав, що вороже військо було поставлено проти нього і спереду і ззаду, і вибрав воїнів з усіх добірних в Ізраїлі, і вишикував їх проти сирійців;","іншу ж частину людей доручив Авессі, братові своєму, щоб він вишикував їх проти аммонитян.","І сказав Іоав: якщо сирійці будуть долати мене, ти допоможеш мені; а якщо аммонитяни тебе будуть долати, я прийду до тебе на допомогу;","будь мужній, і будемо стояти твердо за народ наш і за міста Бога нашого, а Господь зробить, що Йому вгодно.","І вступив Іоав з народом, який був у нього, у битву із сирійцями, і вони побігли від нього.","Аммонитяни ж, побачивши, що сирійці біжать, побігли від Авесси і ввійшли в місто. І повернувся Іоав від аммонитян і прийшов у Єрусалим.","Сирійці, бачачи, що вони уражені ізраїльтянами, зібралися разом.","І послав Адраазар і покликав сирійців, які за річкою [Халамаком], і прийшли вони до Елама; а Совак, воєначальник Адраазарів, начальствував над ними.","Коли донесли про це Давиду, то він зібрав усіх ізраїльтян, і перейшов Йордан і прийшов до Елама. Сирійці вишикувалися проти Давида й билися з ним.","І побігли сирійці від ізраїльтян. Давид знищив у сирійців сімсот колісниць і сорок тисяч вершників; уразив і воєначальника Совака, який там і помер.","Коли всі царі, покірні Адраазару, побачили, що вони уражені ізраїльтянами, то уклали мир з ізраїльтянами і підкорилися їм. А сирійці боялися надалі допомагати аммонитянам."],"x":{"1":"12.19.1","3":"9.3.25|12.19.3","4":"2.19.27|12.19.4","6":"12.19.6-7|9.8.5","10":"12.19.11","12":"8.3.18|12.19.13|54.21.14","15":"12.19.16","18":"12.19.18","19":"12.19.19"}},{"v":["Через рік, у той час, коли виходять царі в походи, Давид послав Іоава і слуг своїх з ним і всіх ізраїльтян; і вони вразили аммонитян і обложили Равву; Давид же залишався в Єрусалимі.","Одного разу надвечір Давид, вставши з постелі, прогулювався на покрівлі царського дому і побачив з покрівлі жінку, яка купається; а та жінка була дуже красива.","І послав Давид розвідати, хто ця жінка? І сказали йому: це Вирсавія, дочка Елиама, дружина Урії хеттеянина.","Давид послав слуг узяти її; і вона прийшла до нього, і він спав з нею. Коли ж вона очистилася від нечистоти своєї, повернулася в дім свій.","Жінка ця зробилася вагітною і послала сповістити Давида, говорячи: я вагітна.","І послав Давид сказати Іоаву: пришли до мене Урію хеттеянина. І послав Іоав Урію до Давида.","І прийшов до нього Урія, і розпитав його Давид про становище Іоава і про становище народу, і про хід війни.","І сказав Давид Урії: йди додому й омий ноги свої. І вийшов Урія з дому царського, а слідом за ним понесли і царську страву.","Але Урія спав біля воріт царського дому з усіма слугами свого господаря, і не пішов у свій дім.","І донесли Давиду, говорячи: не пішов Урія в дім свій. І сказав Давид Урії: ось, ти прийшов з дороги; чому ж не пішов ти в дім свій?","І сказав Урія Давиду: ковчег [Божий] і Ізраїль й Іуда знаходяться в наметах, і господар мій Іоав і раби господаря мого перебувають у полі, а я ввійшов би в дім свій їсти і пити і спати зі своєю дружиною! Клянуся твоїм життям і життям душі твоєї, цього я не зроблю.","І сказав Давид Урії: залишся тут і на цей день, а завтра я відпущу тебе. І залишився Урія в Єрусалимі на цей день до завтра.","І запросив його Давид, і їв Урія перед ним і пив, і напоїв його Давид. Але ввечері Урія пішов спати на постіль свою з рабами господаря свого, а у свій дім не пішов.","Зранку Давид написав листа до Іоава і послав його з Урією.","В листі він написав так: поставте Урію там, де буде найсильніша битва, і відступіть від нього, щоб він був уражений і помер.","Тому, коли Іоав облягав місто, то поставив він Урію на такому місці, про яке знав, що там хоробрі люди.","І вийшли люди з міста й билися з Іоавом, і впали деякі з народу, зі слуг Давидових; був убитий також і Урія хеттеянин.","І послав Іоав донести Давиду про весь хід битви.","І наказав посланому, говорячи: коли ти розповіси цареві про весь хід битви","і побачиш, що цар розгнівався, і скаже тобі: «навіщо ви так близько підходили до міста битися? хіба ви не знали, що зі стіни будуть кидати на вас?","хто убив Авимелеха, сина Ієроваалового? чи не жінка кинула на нього зі стіни уламок жорна [й уразила його], і він помер у Тевеці? Навіщо ж ви близько підходили до стіни?», тоді ти скажи: і раб твій Урія хеттеянин також [уражений і] помер.","І пішов [посланий від Іоава до царя в Єрусалим], і прийшов, і розповів Давиду про все, для чого послав його Іоав, про весь хід битви. [І розгнівався Давид на Іоава і сказав посланому: навіщо ви близько підходили до міста битися? хіба ви не знали, що вас уражати будуть зі стіни? хто убив Авимелеха, сина Ієроваалового? чи не жінка кинула на нього зі стіни уламок жорна, і він помер у Тевеці? Навіщо ви близько підходили до стіни?]","Тоді посланий сказав Давиду: долали нас ті люди і вийшли до нас у поле, і ми переслідували їх до входу у ворота;","тоді стріляли стрільці зі стіни на рабів твоїх, і померли деякі з рабів царя; помер також і раб твій Урія хеттеянин.","Тоді сказав Давид посланому: так скажи Іоаву: «нехай не бентежить тебе ця справа, тому що меч поїдає іноді того, іноді цього; посиль війну твою проти міста і зруйнуй його». Так підбадьор його.","І почула дружина Урії, що помер Урія, чоловік її, і плакала за чоловіком своїм.","Коли скінчився час плачу, Давид послав, і взяв її в дім свій, і вона стала його дружиною і народила йому сина. І було це діло, яке вчинив Давид, зле в очах Господа."],"x":{"1":"12.19.8","2":"30.19.2|50.5.28","3":"12.3.5","4":"10.15.5","8":"0.18.4","15":"9.12.9|10.15.5","21":"6.9.53","24":"9.12.9","26":"4.34.8","27":"30.22.11"}},{"v":["І послав Господь Нафана [пророка] до Давида, і той прийшов до нього і сказав йому: в одному місті було два чоловіка, один багатий, а другий бідний;","у багатого було дуже багато дрібної і великої худоби,","а у бідного нічого, крім однієї овечки, яку він купив маленькою і вигодував, і вона виросла в нього разом з дітьми його; від хліба його вона їла, і з його чаші пила, і на грудях у нього спала, і була для нього, як дочка;","і прийшов до багатої людини подорожній, і той пошкодував узяти зі своїх овець або волів, щоб приготувати [обід] для подорожнього, який прийшов до нього, а взяв овечку бідняка і приготував її для чоловіка, який прийшов до нього.","Сильно розгнівався Давид на цього чоловіка і сказав Нафану: живий Господь! гідний смерти чоловік, який зробив це;","і за овечку він повинен заплатити вчетверо, за те, що він зробив це, і за те, що не мав жалю.","І сказав Нафан Давиду: ти — той чоловік, [який зробив це]. Так говорить Господь Бог Ізраїлів: Я помазав тебе на царя над Ізраїлем і Я визволив тебе від руки Саула,","і дав тобі дім господаря твого і дружин господаря твого на лоно твоє, і дав тобі дім Ізраїлів та Іудин, і, якщо цього [для тебе] мало, додав би тобі ще більше;","навіщо ж ти зневажив слово Господа, зробивши зле перед очима Його? Урію хеттеянина ти вразив мечем; дружину його взяв собі за дружину, а його ти убив мечем аммонитян;","отже, не відступить меч від дому твого повіки, за те, що ти зневажив Мене і взяв дружину Урії хеттеянина, щоб вона була тобі дружиною.","Так говорить Господь: ось, Я пошлю на тебе зло з дому твого, і візьму дружин твоїх перед очима твоїми, і віддам ближньому твоєму, і буде він спати з дружинами твоїми перед цим сонцем;","ти зробив таємно, а Я зроблю це перед усім Ізраїлем і перед сонцем.","І сказав Давид Нафану: згрішив я перед Господом. І сказав Нафан Давиду: і Господь зняв з тебе гріх твій; ти не помреш;","але оскільки ти цим ділом подав привід ворогам Господа хулити Його, то помре народжений у тебе син.","І пішов Нафан у дім свій. І вразив Господь дитя, яке народила дружина Урії Давиду, і воно занедужало.","І молився Давид Богу за немовля, і постився Давид, і, усамітнившись, провів ніч, лежачи на землі.","І ввійшли до нього старійшини дому його, щоб підняти його з землі; але він не хотів, і не їв з ними хліба.","На сьомий день дитя померло, і слуги Давидові боялися донести йому, що померло немовля; тому що, говорили вони, коли немовля було ще живе, і ми умовляли його, і він не слухав голосу нашого, як же ми скажемо йому: «померло дитя»? Він зробить що-небудь зле.","І побачив Давид, що слуги його перешіптуються між собою, і зрозумів Давид, що дитя померло, і запитав Давид слуг своїх: померло дитя? І сказали: померло.","Тоді Давид встав із землі й умився, і помазався, і перемінив одяг свій, і пішов у дім Господній, і молився. Повернувшись додому, повелів, щоб подали йому хліба, і він їв.","І сказали йому слуги його: що означає, що ти так робиш: коли дитя було ще живе, ти постився і плакав [і не спав]; а коли дитя померло, ти встав і їв хліб [і пив]?","І сказав Давид: доки дитя було живе, я постився і плакав, бо думав: хто знає, чи не помилує мене Господь, і дитя залишиться живим?","А тепер воно померло; навіщо ж мені поститися? Хіба я можу повернути його? Я піду до нього, а воно не повернеться до мене.","І утішив Давид Вирсавію, дружину свою, і ввійшов до неї і спав з нею; і вона [зачала і] народила сина, і нарекла йому ім’я: Соломон. І Господь полюбив його","і послав пророка Нафана, і він нарік йому ім’я: Ієдидія* за словом Господа.","Іоав воював проти Равви аммонитської і майже взяв цареве місто.","І послав Іоав до Давида сказати йому: я напав на Равву й оволодів водою міста;","тепер збери інших людей і підступи до міста і візьми його; тому що, коли я візьму його, то моє ім’я буде наречене йому.","І зібрав Давид весь народ і пішов до Равви, і воював проти неї і взяв її.","І взяв Давид вінець царя їх з голови його, — а в ньому було золота талант і дорогоцінний камінь, — і поклав його Давид на свою голову, і здобичі з міста виніс дуже багато.","А людей, які були у ньому, він вивів і поклав їх під пилки, під залізні молотарки, під залізні сокири, і кинув їх у випалювальні печі. Так він учинив з усіма містами аммонитськими. І повернувся після того Давид і весь народ в Єрусалим."],"x":{"5":"62.2.1","6":"1.22.1","7":"10.20.40|8.16.13|12.11.3","9":"9.11.4","10":"10.21.19","11":"9.16.22","13":"30.47.13","14":"31.52.5|36.36.20","24":"50.1.6","26":"12.20.1","30":"12.20.2","31":"9.8.2|31.41.15"},"n":{"25":["Улюблений Богом."]}},{"v":["І було після того: в Авессалома, сина Давидового, була сестра красива, на ім’я Фамар, і полюбив її Амнон, син Давида.","Й уболівав Амнон до того, що занедужав через Фамар, сестру свою; тому що вона була дівчина, і Амнону здавалося тяжким що-небудь зробити з нею.","Але в Амнона був друг, на ім’я Іонадав, син Самая, брата Давидового; і був Іонадав людиною дуже хитрою.","І він сказав йому: від чого ти так худнеш з кожним днем, сину царя, — чи не відкриєш мені? І сказав йому Амнон: Фамар, сестру Авессалома, брата мого, люблю я.","І сказав йому Іонадав: лягай у постіль твою, і прикинься хворим; і коли батько твій прийде відвідати тебе, скажи йому: нехай прийде Фамар, сестра моя, і підкріпить мене їжею, приготувавши страву на моїх очах, щоб я бачив, і їв з рук її.","І ліг Амнон і прикинувся хворим, і прийшов цар відвідати його; і сказав Амнон царю: нехай прийде Фамар, сестра моя, і спече на моїх очах корж, або два, і я поїм з рук її.","І послав Давид до Фамар в дім сказати: піди в дім Амнона, брата твого, і приготуй йому страву.","І пішла вона в дім брата свого Амнона; а він лежить. І взяла вона борошна і замісила, і приготувала на очах його і спекла коржі,","і взяла сковороду і виклала перед ним; але він не хотів їсти. І сказав Амнон: нехай усі вийдуть від мене. І вийшли від нього всі люди,","і сказав Амнон Фамар: віднеси страву у внутрішню кімнату, і я поїм з рук твоїх. І взяла Фамар коржі, що приготувала, і віднесла Амнону, братові своєму, у внутрішню кімнату.","І коли вона поставила перед ним, щоб він їв, то він схопив її, і сказав їй: іди, лягай зі мною, сестро моя.","Але вона сказала: ні, брате мій, не знечещуй мене, тому що не робиться так в Ізраїлі; не роби цього безумства.","І я, куди я піду з моїм нечестям? І ти, ти будеш одним із безумних в Ізраїлі. Ти поговори з царем; він не відмовить віддати мене тобі.","Але він не хотів слухати слів її, і переборов її, і зґвалтував її, і лежав з нею.","Потім зненавидів її Амнон величезною ненавистю, так що ненависть, якою він зненавидів її, була сильнішою за любов, яку мав до неї; і сказав Амнон: встань, іди.","І [Фамар] сказала йому: ні, [брате]; прогнати мене — це зло більше за перше, яке ти зробив із мною. Але він не хотів слухати її.","І покликав слугу свого, який служив йому, і сказав: прожени цю від мене геть і замкни двері за нею.","На ній був різнобарвний одяг, бо такий верхній одяг носили царські дочки-дівчата. І вивів її слуга геть і замкнув за нею двері.","І посипала Фамар попелом голову свою, і роздерла різнобарвний одяг, який мала на собі, і поклала руки свої на голову свою, і так ішла і волала.","І сказав їй Авессалом, брат її: чи не Амнон, брат твій, був з тобою? — але тепер мовчи, сестро моя; він — брат твій; не тужи серцем твоїм про цю справу. І жила Фамар на самоті в домі Авессалома, брата свого.","І почув цар Давид про все це, і дуже розгнівався, [але не засмутив духу Амнона, сина свого, тому що любив його, бо він був первісток його].","Авессалом же не говорив з Амноном ні поганого, ні доброго; бо зненавидів Авессалом Амнона за те, що він знечестив Фамар, сестру його.","Через два роки було стриження овець в Авессалома у Ваал-Гацорі, що в Єфрема, і покликав Авессалом усіх синів царських.","І прийшов Авессалом до царя і сказав: ось, нині стриження овець у раба твого; нехай піде цар і слуги його з рабом твоїм.","Але цар сказав Авессалому: ні, сину мій, ми не підемо всі, щоб не бути тобі за тягар. І сильно просив його Авессалом; але він не захотів іти, і благословив його.","І сказав йому Авессалом: принаймні нехай піде з нами Амнон, брат мій. І сказав йому цар: навіщо йому йти з тобою?","Але Авессалом ублагав його, і він відпустив з ним Амнона і всіх царських синів; [і зробив Авессалом бенкет, як цар робить бенкет].","Авессалом же наказав слугам своїм, сказавши: дивіться, як тільки розвеселиться серце Амнона від вина, і я скажу вам: «уразьте Амнона», тоді убийте його, не бійтеся; це я наказую вам, будьте сміливі й мужні.","І вчинили слуги Авессалома з Амноном, як наказав Авессалом. Тоді встали всі царські сини, сіли кожен на мула свого й утекли.","Коли вони були ще в дорозі, дійшла чутка до Давида, що Авессалом умертвив усіх царських синів, і не залишилося жодного з них.","І встав цар, і роздер одяг свій, і простягнувся на землі, і всі слуги його, які стоять перед ним, роздерли одяг свій.","Але Іонадав, син Самая, брата Давидового, сказав: нехай не думає господар мій [цар], що всіх отроків, царських синів, умертвили; один тільки Амнон помер, тому що в Авессалома був цей задум з того дня, як Амнон знечестив сестру його;","отже, нехай господар мій, цар, не тривожиться думкою про те, начебто померли всі царські сини: помер один тільки Амнон.","І втік Авессалом. І підняв слуга, який стояв на сторожі, очі свої, і побачив: ось, багато народу йде по дорозі на схилі гори. [І прийшов вартовий, і сповістив царю, і сказав: я бачив людей на дорозі Оронській на схилі гори.]","Тоді Іонадав сказав цареві: це йдуть царські сини; як говорив раб твій, так і є.","І ледь тільки сказав він це, ось прийшли царські сини, і підняли крик і плакали. І сам цар і всі слуги його плакали дуже великим плачем.","Авессалом же утік і пішов до Фалмая, сина Емиуда, царя Гессурського [у землю Хамаахадську]. І плакав [цар] Давид за сином своїм в усі дні.","Авессалом утік і прийшов у Гессур і пробув там три роки.","І не став цар Давид переслідувати Авессалома; бо втішився після смерти Амнона."],"x":{"1":"12.3.1","3":"8.16.9|12.2.13","37":"9.3.3"}},{"v":["І помітив Іоав, син Саруї, що серце царя навернулося до Авессалома.","І послав Іоав у Фекою, і взяв звідти розумну жінку і сказав їй: прикинься, що ти плачеш, і одягни печальний одяг, і не намащуйся єлеєм, і представся жінкою, яка багато днів плакала за померлим;","і піди до царя і скажи йому так і так. І вклав Іоав у вуста її, що сказати.","І ввійшла жінка фекоїтянка до царя й упала лицем своїм на землю, і поклонилася і сказала: допоможи, царю, [допоможи]!","І сказав їй цар: що тобі? І сказала вона: я [давно] вдова, чоловік мій помер;","і у раби твоєї було два сини; вони посварилися в полі, і не було кому розняти їх, і вразив один другого й умертвив його.","І ось, повстали всі родичі на рабу твою, і говорять: «віддай убивцю брата свого; ми вб’ємо його за душу брата його, якого він згубив, і знищимо навіть спадкоємця». І так вони погасять останню іскру мою, щоб не залишити чоловікові моєму імені і потомства на лиці землі.","І сказав цар жінці: йди спокійно додому, я дам наказ про тебе.","Але жінка фекоїтянка сказала цареві: на мені, господарю мій царю, нехай буде провина і на домі батька мого, цар же і престіл його невинний.","І сказав цар: того, хто буде проти тебе, приведи до мене, і він більше не торкнеться тебе.","Вона сказала: пом’яни, царю, Господа Бога твого, щоб не примножилися месники за кров і не погубили сина мого. І сказав цар: живий Господь! не упаде і волосина сина твого на землю.","І сказала жінка: дозволь рабі твоїй сказати ще слово господарю моєму царю.","Він сказав: говори. І сказала жінка: чому ти так думаєш проти народу Божого? Цар, сказавши це слово, звинуватив себе самого, тому що не повертає вигнанця свого.","Ми помремо і будемо, як вода, вилита на землю, яку не можна зібрати; але Бог не бажає погубити душу і помишляє, як би не відкинути від Себе і відкинутого.","І тепер я прийшла сказати цареві, господарю моєму, ці слова, тому що народ лякає мене; і раба твоя сказала: поговорю я з царем, чи не зробить він за словом раби своєї;","цар вислухає і визволить рабу свою від руки людей, які хочуть знищити мене разом із сином моїм із насліддя Божого.","І сказала раба твоя: нехай буде слово господаря мого царя в утіху мені, тому що господар мій цар, як ангел Божий, і може вислухати і добре і лихе. І Господь Бог твій буде з тобою.","І відповів цар і сказав жінці: не втаї від мене, про що я запитаю тебе. І сказала жінка: говори, господарю мій царю.","І сказав цар: чи не рука Іоава у всьому цьому з тобою? І відповіла жінка і сказала: нехай живе душа твоя, господарю мій царю; ні праворуч, ні ліворуч не можна ухилитися від того, що сказав господар мій, цар; справді, раб твій Іоав наказав мені, і він вклав у вуста раби твоєї усі ці слова;","щоб притчею дати ділу такий вигляд, раб твій Іоав навчив мене; але господар мій [цар] мудрий, як мудрий ангел Божий, щоб знати все, що на землі.","І сказав цар Іоаву: ось, я зробив [за словом твоїм]; піди ж, поверни отрока Авессалома.","Тоді Іоав упав лицем на землю і поклонився, і благословив царя і сказав: тепер знає раб твій, що знайшов благовоління перед очима твоїми, господарю мій царю, тому що цар зробив за словом раба свого.","І встав Іоав, і пішов у Гессур, і привів Авессалома в Єрусалим.","І сказав цар: нехай він повернеться в дім свій, а лиця мого не бачить. І пішов Авессалом у свій дім, а лиця царевого не бачив.","Не було в усьому Ізраїлі чоловіка настільки красивого, як Авессалом, і стільки хвалимого, як він; від підошви ніг до верха голови його не було в нього недоліку.","Коли він стриг голову свою, — а він стриг її щороку, тому що вона обтяжувала його, — то волосся з голови його важило двісті сиклів за вагою царською.","І народилися в Авессалома три сини й одна дочка, на ім’я Фамар; вона була жінка красива [і стала дружиною Ровоама, сина Соломонового, і народила йому Авию].","І залишався Авессалом в Єрусалимі два роки, а лиця царевого не бачив.","І послав Авессалом за Іоавом, щоб послати його до царя, але той не захотів прийти до нього. Послав і вдруге; але той не захотів прийти.","І сказав [Авессалом] слугам своїм: бачите ділянку поля Іоава поряд з моїм, і в нього там ячмінь; підіть, випаліть його вогнем. І випалили слуги Авессалома ту ділянку поля вогнем. [І прийшли слуги Іоава до нього, роздерши одяг свій, і сказали: слуги Авессалома випалили ділянку твою вогнем.]","І встав Іоав, і прийшов до Авессалома в дім, і сказав йому: навіщо слуги твої випалили мою ділянку вогнем?","І сказав Авессалом Іоаву: ось, я посилав за тобою, говорячи: прийди сюди, і я пошлю тебе до царя сказати: навіщо я прийшов з Гессура? Краще було б мені залишатися там. Я хочу побачити лице царя. Якщо ж я винен, то убий мене.","І пішов Іоав до царя і переказав йому це. І покликав цар Авессалома; він прийшов до царя, [поклонився йому] й упав лицем своїм на землю перед царем; і поцілував цар Авессалома."],"x":{"2":"9.23.26|13.11.6","4":"8.20.41|9.1.2","7":"3.35.19:21|4.19.12|9.21.17","11":"29.6.21","14":"36.18.32|36.33.11","16":"4.32.9|25.93.5","17":"8.29.9|9.19.27","20":"20.5.2","22":"8.25.24","23":"12.3.2|9.13.37","25":"10.1.6","26":"9.18.9","27":"9.13.1"}},{"v":["Після цього Авессалом завів у себе колісниці і коней і п’ятдесят скороходів.","І вставав Авессалом рано-вранці, і ставав при дорозі біля воріт, і коли хто-небудь, маючи позов, ішов до царя на суд, то Авессалом підкликав його до себе і запитував: з якого міста ти? І коли той відповідав: з такого-то коліна Ізраїлевого раб твій,","тоді говорив йому Авессалом: ось, справа твоя добра і справедлива, але у царя нема кому вислухати тебе.","І говорив Авессалом: о, якби мене поставили суддею в цій землі! До мене приходив би всякий, хто має суперечку і позов, і я судив би його за правдою.","І коли підходив хто-небудь поклонитися йому, то він простягав руку свою й обіймав його і цілував його.","Так робив Авессалом із кожним ізраїльтянином, який приходив на суд до царя, і приваблював Авессалом до себе серця ізраїльтян.","Коли минуло сорок років царювання Давида, Авессалом сказав цареві: піду я і виконаю обітницю мою, яку я дав Господу, у Хевроні;","бо я, раб твій, живучи в Гессурі в Сирії, дав обітницю: якщо Господь поверне мене в Єрусалим, то я принесу жертву Господу.","І сказав йому цар: іди з миром. І встав він і пішов у Хеврон.","І розіслав Авессалом спостерігачів в усі коліна Ізраїлеві, сказавши: коли ви почуєте звук труби, то говоріть: Авессалом став царем у Хевроні.","З Авессаломом пішли з Єрусалима двісті чоловік, які були запрошені ним, і пішли з простоти своєї, не знаючи, в чому справа.","Під час жертвоприношення Авессалом послав і прикликав Ахитофела гилонянина, радника Давидового, з його міста Гило. І склалася сильна змова, і народ стікався і збільшувався навколо Авессалома.","І прийшов вісник до Давида і сказав: серце ізраїльтян схилилося на бік Авессалома.","І сказав Давид усім слугам своїм, які були при ньому в Єрусалимі: встаньте, втечімо, тому що не буде нам порятунку від Авессалома; поспішайте, щоб нам утекти, щоб він не застиг і не захопив нас, і не навів на нас лиха і не знищив міста мечем.","І сказали слуги царські царю: в усьому, що вгодно господарю нашому царю, ми — раби твої.","І вийшов цар і весь дім його за ним пішки. Залишив же цар десять дружин, наложниць [своїх], для збереження дому.","І вийшов цар і весь народ пішки, і зупинилися в Беф-Мерхата.","І всі слуги його йшли по боках його, і всі хелефеї, і всі фелефеї, і всі гефяни до шестисот чоловік, які прийшли разом з ним з Гефа, йшли попереду царя.","І сказав цар Еффею гефянину: навіщо і ти йдеш з нами? Повернися і залишайся з тим царем; тому що ти — чужеземець і прийшов сюди зі свого місця;","вчора ти прийшов, а сьогодні я змушу тебе йти з нами? Я йду, куди трапиться; повернися і поверни братів своїх із собою, [нехай учинить Господь] милість і істину [з тобою]!","І відповів Еффей царю і сказав: живий Господь, і нехай живе господар мій цар: де б не був господар мій цар, чи в житті, а чи у смерті, там буде і раб твій.","І сказав Давид Еффею: отже, йди і ходи зі мною. І пішов Еффей гефянин і всі люди його і всі діти, які були з ним.","І плакала вся земля голосно. І весь народ переходив, і цар перейшов потік Кедрон; і пішов весь народ [і цар] по дорозі до пустелі.","Ось і Садок [священик], і всі левити з ним несли ковчег завіту Божого з Вефари і поставили ковчег Божий; Авиафар же стояв на підвищенні, доки весь народ не вийшов з міста.","І сказав цар Садокові: поверни ковчег Божий у місто [і нехай він стоїть на своєму місці]. Якщо я знайду милість перед очима Господа, то Він поверне мене і дасть мені бачити його й оселю його.","А якщо Він скаже так: «немає Мого благовоління до тебе», то ось я; нехай творить зі мною, що Йому благовгодно.","І сказав цар Садоку священику: чи бачиш, — повернися в місто з миром, і Ахимаас, син твій, і Іонафан, син Авиафара, обидва сини ваші з вами;","чи бачите, я затримаюся на рівнині в пустелі, доки не прийде звістка від вас до мене.","І повернули Садок і Авиафар ковчег Божий в Єрусалим, і залишилися там.","А Давид пішов на гору Елеонську, йшов і плакав; голова в нього була покрита; він ішов босий, і всі люди, які були з ним, покрили кожен голову свою, йшли і плакали.","Донесли Давиду і сказали: і Ахитофел у числі змовників з Авессаломом. І сказав Давид: Господи [Боже мій!] зруйнуй раду Ахитофела.","Коли Давид зійшов на вершину гори, де він поклонявся Богу, ось назустріч йому йде Хусій архитянин, друг Давидів; одяг на ньому був розідраний, і порох на голові його.","І сказав йому Давид: якщо ти підеш зі мною, то будеш мені за тягар;","але якщо повернешся в місто і скажеш Авессалому: «царю, [пройшли мимо брати твої, і цар батько твій пройшов, і нині] я раб твій; [залиш мене в живих;] досі я був рабом батька твого, а тепер я — твій раб»: то ти зруйнуєш для мене раду Ахитофела.","Ось, там з тобою Садок і Авиафар священики, і всяке слово, яке почуєш з дому царя, переказуй Садоку й Авиафару священикам.","Там з ними і два сини їхні, Ахимаас, син Садока, та Іонафан, син Авиафара; через них посилайте до мене всяку звістку, яку почуєте.","І прийшов Хусій, друг Давидів, у місто; Авессалом же вступав тоді в Єрусалим."],"x":{"1":"10.1.5","3":"9.8.15","8":"9.16.21","10":"62.13.2","12":"9.17.23|12.27.33","14":"25.3.1","16":"9.16.21","18":"9.8.18|12.18.17","19":"9.18.2","21":"7.1.16","23":"10.2.37|32.31.40|53.18.1","24":"8.22.20","25":"9.16.12|25.41.5","26":"9.10.12|50.6.10|54.21.14","28":"11.25.5|9.17.16","30":"50.26.30:37|75.5.7|9.19.4","31":"9.16.23","34":"9.17.7|52.1.51","37":"9.16.16|12.27.33"}},{"v":["Коли Давид трохи зійшов з вершини гори, ось зустрічається йому Сива, слуга Мемфивосфея, з парою нав’ючених ослів, і на них двісті хлібів, сто зв’язок ізюма, сто зв’язок смокв і міх з вином.","І сказав цар Сиві: для чого це в тебе? І відповів Сива: осли для дому царського, для їзди, а хліб і плоди для їжі слугам, а вино для пиття ослаблим у пустелі.","І сказав цар: де син господаря твого? І відповів Сива цареві: ось, він залишився в Єрусалимі і говорить: тепер дім Ізраїлів поверне мені царство батька мого.","І сказав цар Сиві: ось тобі все, що в Мемфивосфея. І відповів Сива, поклонившись: нехай знайду милість в очах господаря мого царя!","Коли дійшов цар Давид до Бахурима, ось вийшов звідти чоловік з роду дома Саулового, на ім’я Семей, син Гери; він ішов і лихословив,","і кидав каменями на Давида і на всіх рабів царя Давида; всі ж люди і всі хоробрі були праворуч і ліворуч [царя].","Так говорив Семей, лихословлячи його: іди, іди, убивця і беззаконник!","Господь повернув на тебе всю кров дому Саулового, замість якого ти став царем, і віддав Господь царство в руки Авессалома, сина твого; і ось, ти в біді, бо ти — кровожер.","І сказав Авесса, син Саруїн, царю: навіщо лихословить цей мертвий пес господаря мого царя? піду я і зніму з нього голову.","І сказав цар: що мені і вам, сини Саруїни? [залиште його,] нехай він лихословить, тому що Господь повелів йому лихословити Давида. Хто ж може сказати: навіщо ти так робиш?","І сказав Давид Авессі і всім слугам своїм: ось, якщо мій син, який вийшов із стегон моїх, шукає душі моєї, тим більше син веніамитянина; залиште його, нехай лихословить, тому що Господь повелів йому;","може бути, Господь зглянеться на приниження моє, і воздасть мені Господь благістю за теперішнє його лихослів’я.","І йшов Давид і люди його своєю дорогою, а Семей ішов по краю гори, з боку його, йшов і лихословив, і кидав каменями в бік його і пилом.","І прийшов цар і весь народ, який був з ним, стомлений, і відпочивав там.","Авессалом же і весь народ ізраїльський прийшли в Єрусалим, і Ахитофел з ним.","Коли Хусій архитянин, друг Давидів, прийшов до Авессалома, то сказав Хусій Авессалому: нехай живе цар, нехай живе цар!","І сказав Авессалом Хусію: така твоя ревність до твого друга! чому ти не пішов із другом твоїм?","І сказав Хусій Авессалому: ні, [я піду услід того,] кого обрав Господь і цей народ і весь Ізраїль, з тим і я, і з ним залишусь.","І притому кому я буду служити? Чи не синові його? Як служив я батькові твоєму, так буду служити і тобі.","І сказав Авессалом Ахитофелу: дай пораду, що нам робити.","І сказав Ахитофел Авессалому: увійди до наложниць батька твого, яких він залишив охороняти дім свій; і почують усі ізраїльтяни, що ти став ненависним для батька твого, і зміцняться руки всіх, хто з тобою.","І поставили для Авессалома намет на покрівлі, і ввійшов Авессалом до наложниць батька свого перед очима всього Ізраїля.","Поради ж Ахитофела, які він давав, у той час вважалися, наче якби хто запитував наставляння в Бога. Такою була всяка рада Ахитофела як для Давида, так і для Авессалома."],"x":{"1":"9.9.2","3":"9.19.26","4":"9.19.29","5":"9.3.16|10.2.8","7":"25.5.7","9":"9.19.21","10":"24.5.7","11":"9.19.16|1.22.28","12":"9.15.25","13":"10.2.8","16":"9.15.37","21":"9.15.16","22":"9.12.11","23":"9.15.31"}},{"v":["І сказав Ахитофел Авессалому: виберу я дванадцять тисяч чоловік і встану і піду в погоню за Давидом у цю ніч;","і нападу на нього, коли він буде стомлений і з опущеними руками, і приведу його в страх; і всі люди, які з ним, розбіжаться; і я уб’ю одного царя","і всіх людей поверну до тебе; і коли не буде одного, душу якого ти шукаєш, тоді весь народ буде в мирі.","І сподобалося це слово Авессалому і всім старійшинам Ізраїлевим.","І сказав Авессалом: покличте Хусія архитянина; послухаємо, що він скаже.","І прийшов Хусій до Авессалома, і сказав йому Авессалом, говорячи: ось що говорить Ахитофел; чи зробити за його словами? а якщо ні, то говори ти.","І сказав Хусій Авессалому: недобра цього разу порада, яку дав Ахитофел.","І продовжував Хусій: ти знаєш твого батька і людей його; вони хоробрі і сильно роздратовані, як ведмедиця в полі, у якої відняли дітей, [і як вепр лютий на полі,] і батько твій — людина войовнича; він не зупиниться ночувати з народом.","Ось, тепер він ховається в якій-небудь печері, або в іншому місці, і якщо хто впаде при першому нападі на них, і почують і скажуть: «була поразка людей, які пішли за Авессаломом»,","тоді і найхоробріший, у якого серце, як серце левине, впаде духом; тому що всьому Ізраїлю відомо, який хоробрий батько твій і мужні ті, які з ним.","Тому я раджу: нехай збереться до тебе весь Ізраїль, від Дана до Вирсавії, у безлічі, як пісок при морі, і ти сам підеш серед нього;","і тоді ми підемо проти нього, в якому б місці він не знаходився, і нападемо на нього, як падає роса на землю; і не залишиться в нього жодної людини з усіх, хто з ним;","а якщо він увійде в яке-небудь місто, то весь Ізраїль принесе до того міста мотузки, і ми стягнемо його в ріку, так що не залишиться жодного камінчика.","І сказав Авессалом і весь Ізраїль: порада Хусія архитянина краща за пораду Ахитофела. Так Господь судив зруйнувати кращу пораду Ахитофела, щоб навести Господу біду на Авессалома.","І сказав Хусій Садокові й Авиафарові священикам: так і так радив Ахитофел Авессалому і старійшинам Ізраїлевим, а так і так порадив я.","І тепер пошліть швидше і скажіть Давиду так: не залишайся в цю ніч на рівнині в пустелі, але швидше перейди, щоб не загинути царю і всім людям, які з ним.","Іонафан і Ахимаас стояли біля джерела Рогель. І пішла служниця і розповіла їм, а вони пішли і сповістили царя Давида; бо вони не могли показатися в місті.","І побачив їх слуга і доніс Авессалому; але вони обидва незабаром пішли і прийшли в Бахурим, у дім одного чоловіка, в якого у дворі був колодязь, і спустилися туди.","А жінка взяла і розтягла над отвором колодязя покривало і насипала на нього крупи, так що не було нічого помітно.","І прийшли раби Авессалома до жінки в дім, і сказали: де Ахимаас та Іонафан? І сказала їм жінка: вони перейшли убрід ріку. І шукали вони, і не знайшли, і повернулися в Єрусалим.","Коли вони пішли, ті вийшли з колодязя, пішли і сповістили царя Давида і сказали Давиду: встаньте і швидше перейдіть воду; бо так і так радив про вас Ахитофел.","І встав Давид і всі люди, які були з ним, і перейшли Йордан; до світанку не залишилося жодного, який не перейшов би Йордан.","І побачив Ахитофел, що не виконали поради його, і осідлав осла, і зібрався, і пішов у дім свій, у місто своє, і зробив заповіт дому своєму, і повісився, і помер, і був похований у гробі батька свого.","І прийшов Давид у Маханаїм, а Авессалом перейшов Йордан, сам і весь Ізраїль з ним.","Авессалом поставив Амессая, замість Іоава, над військом. Амессай був сином одного чоловіка, на ім’я Ієфера з Ізрееля, який ввійшов до Авигеї, дочки Нааса, сестри Саруї, матері Іоава.","І Ізраїль з Авессаломом розташувався станом в землі Галаадській.","Коли Давид прийшов у Маханаїм, то Сови, син Нааса, з Равви аммонитської, і Махир, син Аммиїла, з Лодавара, і Верзеллій галаадитянин з Роглима,","принесли [десять приготованих] постелей, [десять] блюд і глиняних посудин, і пшениці, і ячменю, і борошна, і пшона, і бобів, і сочевиці, і смажених зерен,","і меду, й олії, і овець, і сиру коров’ячого, принесли Давиду і людям, які були з ним, у їжу; бо говорили вони: народ голодний і стомлений і терпів спрагу в пустелі."],"x":{"1":"25.54.4","2":"9.16.14","7":"9.15.34","9":"6.6.2","14":"9.15.31|24.5.13|25.32.10","17":"9.15.27","19":"5.2.4","21":"9.15.28","23":"9.15.12","25":"9.19.13","27":"9.19.31","29":"9.16.2"}},{"v":["І оглянув Давид людей, які були з ним, і поставив над ними тисячоначальників і сотників.","І відправив Давид людей — третю частину під проводом Іоава, третю частину під проводом Авесси, сина Саруїного, брата Іоава, третю частину під проводом Еффея гефянина. І сказав цар людям: я сам піду з вами.","Але люди відповіли йому: не ходи; бо, якщо ми і побіжимо, то не звернуть уваги на це; якщо і помре половина з нас, також не звернуть уваги; а ти один те саме, що нас десять тисяч; отже, для нас краще, щоб ти допомагав нам з міста.","І сказав їм цар: що угодно в очах ваших, те і зроблю. І став цар біля воріт, і весь народ виходив по сотнях і по тисячах.","І наказав цар Іоаву й Авессі й Еффею, говорячи: збережіть мені отрока Авессалома. І всі люди чули, як наказував цар усім начальникам про Авессалома.","І вийшли люди в поле назустріч ізраїльтянам, і була битва у лісі Єфремовому.","І був уражений народ ізраїльський рабами Давида; була там поразка велика в той день, — уражені двадцять тисяч [чоловік].","Битва поширилася по всьому тому краю, і ліс погубив народу більше, ніж скільки знищив меч, у той день.","І зустрівся Авессалом з рабами Давидовими; він був на мулі. Коли мул вбіг з ним під гілки великого дуба, то Авессалом заплутався волоссям своїм у гілках дуба і повис між небом і землею, а мул, який був під ним, утік.","І побачив це хтось і доніс Іоаву, говорячи: ось, я бачив Авессалома, що висить на дубі.","І сказав Іоав чоловікові, який доніс про це: ось, ти бачив; чому ж ти не повалив його там на землю? я дав би тобі десять сиклів срібла й один пояс.","І відповів той Іоаву: якби поклали в руки мої і тисячу сиклів срібла, і тоді я не підняв би руки на царського сина; бо ми чули, як цар наказував тобі й Авессі та Еффею, говорячи: «збережіть мені отрока Авессалома»;","і якби я зробив інакше з небезпекою для життя мого, то це не утаїлося б від царя, і ти ж повстав би проти мене.","Іоав сказав: нема чого мені баритися з тобою. І взяв у руки три стріли і встромив їх у серце Авессалома, який був ще живий на дубі.","І оточили Авессалома десять слуг, зброєносців Іоава, й уразили й умертвили його.","І засурмив Іоав трубою, і повернулися люди з погоні за Ізраїлем, бо Іоав щадив народ.","І взяли Авессалома, і кинули його в лісі у глибоку яму, і навалили над ним величезну купу каміння. І всі ізраїльтяни розбіглися, кожен у намет свій.","Авессалом ще за життя свого взяв і поставив собі пам’ятник у царській долині; бо сказав він: немає в мене сина, щоб збереглася пам’ять імені мого. І назвав пам’ятник своїм ім’ям. І називається він «пам’ятник Авессалома» до цього дня.","Ахимаас, син Садоків, сказав Іоаву: побіжу я, сповіщу царя, що Господь судом Своїм визволив його від рук ворогів його.","Але Іоав сказав йому: не будеш ти сьогодні добрим вісником; сповістиш в інший день, а не сьогодні, тому що помер син царя.","І сказав Іоав Хусію: піди, донеси цареві, що бачив ти. І поклонився Хусій Іоаву і побіг.","Але Ахимаас, син Садоків, наполягав і говорив Іоаву: що б не було, але і я побіжу за Хусієм. Іоав же відповів: навіщо бігти тобі, сину мій? не принесеш ти доброї вістки.","[І сказав Ахимаас:] нехай так, але я побіжу. І сказав йому [Іоав]: біжи. І побіг Ахимаас по прямій дорозі і випередив Хусія.","Давид тоді сидів між двома воротами. І сторож піднявся на покрівлю воріт до стіни і, звівши очі, побачив: ось, біжить одна людина.","І закричав сторож і сповістив царя. І сказав цар: якщо один, то вістка у вустах його. А той підходив усе ближче і ближче.","Сторож побачив і іншу людину, яка біжить; і закричав сторож воротареві: ось, ще біжить одна людина. Цар сказав: і це — вісник.","Сторож сказав: я бачу ходу першого, схожу на ходу Ахимааса, сина Садокового. І сказав цар: це людина добра і йде з хорошою вісткою.","І викликнув Ахимаас і сказав цареві: мир. І поклонився цареві лицем своїм до землі і сказав: благословенний Господь Бог твій, що видав людей, які підняли руки свої на господаря мого царя!","І сказав цар: чи благополучний отрок Авессалом? І сказав Ахимаас: я бачив велике хвилювання, коли раб царя Іоав посилав раба твого; але я не знаю, що [там] було.","І сказав цар: відійди, стань тут. Він відійшов і став.","Ось, прийшов і Хусій [слідом за ним]. І сказав Хусій [царю]: добра звістка господарю моєму цареві! Господь явив тобі нині правду у спасінні від руки всіх, хто повстав проти тебе.","І сказав цар Хусію: чи благополучний отрок Авессалом? І сказав Хусій: нехай буде з ворогами господаря мого царя і з усіма, хто замишляє лихе проти тебе, те саме, що стало з отроком!","І засмутився цар, і пішов у світлицю над воротами, і плакав, і коли йшов, говорив так: сину мій Авессаломе! сину мій, сину мій Авессаломе! о, хто дав би мені померти замість тебе, Авессаломе, сину мій, сину мій!"],"x":{"2":"9.15.19","3":"9.21.17|8.18.7|30.47.7","9":"9.14.26","17":"5.7.26","18":"0.14.17|9.14.27","19":"12.6.8","31":"10.1.42"}},{"v":["І сказали Іоаву: ось, цар плаче і ридає за Авессаломом.","І обернулася перемога того дня на плач для всього народу; бо народ почув у той день і говорив, що цар у скорботі за свого сина.","І входив тоді народ у місто крадькома, як скрадаються люди, які соромляться, що під час битви кинулися навтіки.","А цар закрив лице своє і голосно взивав: сину мій Авессаломе! Авессаломе, сину мій, сину мій!","І прийшов Іоав до царя в дім і сказав: ти в сором привів сьогодні всіх слуг твоїх, які врятували нині життя твоє і життя синів і дочок твоїх, і життя дружин і життя наложниць твоїх;","ти любиш ненависників твоїх і ненавидиш тих, що люблять тебе, бо ти показав сьогодні, що ніщо для тебе і вожді і слуги; сьогодні я довідався, що якби Авессалом залишився живий, а ми усі померли, то тобі було б приємніше;","отже, встань, вийди і поговори до серця рабів твоїх, бо клянуся Господом, що, коли ти не вийдеш, у цю ніч не залишиться в тебе жодної людини; і це буде для тебе гірше за всі біди, які находили на тебе від юности твоєї донині.","І встав цар і сів біля воріт, а весь народ сповістили, що цар сидить біля воріт. І прийшов весь народ перед лице царя [до воріт]; ізраїльтяни ж розбіглися по своїх наметах.","І весь народ у всіх колінах Ізраїлевих сперечався і говорив: цар [Давид] визволив нас від рук ворогів наших і звільнив нас від рук филистимлян, а тепер сам утікав із землі цієї [з царства свого] від Авессалома.","Але Авессалом, якого ми помазали на царя над нами, помер на війні; чому ж тепер ви баритеся повернути царя? [І ці слова всього Ізраїля дійшли до царя.]","І цар Давид послав сказати священикам Садокові й Авиафарові: скажіть старійшинам Іудиним: чому ви хочете бути останніми, щоб повернути царя в дім його, тоді як слова всього Ізраїля дійшли до царя в дім його?","Ви брати мої, кості мої і плоть моя — ви; чому ви хочете бути останніми в поверненні царя в дім його?","І Амессаю скажіть: чи не кость моя і плоть моя — ти? Нехай те і те зробить зі мною Бог і ще більше зробить, якщо ти не будеш воєначальником при мені, замість Іоава, назавжди!","І прихилив він серце всіх юдеїв, як однієї людини; і послали вони до царя сказати: повернися ти й усі слуги твої.","І повернувся цар, і прийшов до Йордану, а юдеї прийшли в Галгал, щоб зустріти царя і перевезти царя через Йордан.","І поспішив Семей, син Гери, веніамитянин з Бахурима, і пішов з юдеями назустріч царю Давиду,","і тисяча чоловік з веніамитян з ним, і Сива, слуга дому Саулового, з п’ятнадцятьма синами своїми і двадцятьма рабами своїми; і перейшли вони Йордан перед лицем царя [і приготували для царя переправу через Йордан].","Коли переправили судно, щоб перевезти дім царя і послужити йому, тоді Семей, син Гери, упав [на лице своє] перед царем, як тільки він перейшов Йордан,","і сказав цареві: не постав мені, господарю мій, за злочин, і не пом’яни того, чим згрішив раб твій у той день, коли господар мій цар виходив з Єрусалима, і не тримай того, царю, на серці своєму;","бо знає раб твій, що згрішив, і ось, нині я прийшов перший з усього дому Йосифового, щоб вийти назустріч господареві моєму царю.","І відповів Авесса, син Саруїн, і сказав: невже Семей не помре за те, що лихословив помазаника Господнього?","І сказав Давид: що мені і вам, сини Саруїни, що ви робитеся нині мені наклепниками? Чи нині умертвляти кого-небудь в Ізраїлі? Чи не бачу я, що нині я — цар над Ізраїлем?","І сказав цар Семею: ти не помреш. І поклявся йому цар.","І Мемфивосфей, син [Іонафана, сина] Саулового, вийшов назустріч цареві. Він не омивав ніг своїх, [не обрізував нігтів,] не піклувався про бороду свою і не мив одягу свого з того дня, як вийшов цар, до дня, коли він повернувся з миром.","Коли він вийшов з Єрусалима назустріч царю, цар сказав йому: чому ти, Мемфивосфею, не пішов зі мною?","Той відповів: господарю мій царю! слуга мій обманув мене; бо я, раб твій, говорив: «осідлаю собі осла і сяду на нього і поїду з царем», оскільки раб твій кульгавий.","А він звів наклеп на раба твого перед господарем моїм царем. Але господар мій цар, як ангел Божий; роби, що тобі угодно;","хоча весь дім батька мого був повинен умерти перед господарем моїм царем, але ти посадив раба твого між тими, хто їсть за столом твоїм; яке ж маю я право скаржитися ще перед царем?","І сказав йому цар: до чого ти говориш усе це? я сказав, щоб ти і Сива розділили між собою поля.","Але Мемфивосфей відповів цареві: нехай він візьме навіть усе, після того як господар мій цар з миром повернувся в дім свій.","І Верзеллій галаадитянин прийшов з Роглима і перейшов із царем Йордан, щоб провести його за Йордан.","Верзеллій же був дуже старий, років вісімдесяти. Він постачав царя продовольством під час перебування його в Маханаїмі, тому що був людиною багатою.","І сказав цар Верзеллію: йди зі мною, і я буду годувати тебе в Єрусалимі.","Але Верзеллій відповів цареві: чи довго мені залишилося жити, щоб іти з царем в Єрусалим?","Мені тепер вісімдесят років; чи відрізню добре від злого? Чи узнає раб твій смак того, що буду їсти, і того, що буду пити? І чи буду у змозі чути голос співаків і співачок? Навіщо ж рабу твоєму бути за тягар господарю моєму царю?","Ще трохи пройде раб твій з царем за Йордан; за що ж царю нагороджувати мене такою милістю?","Дозволь рабу твоєму повернутися, щоб померти у своєму місті, біля гробу батька мого і матері моєї. Але ось, раб твій [син мій] Кимгам нехай піде з господарем моїм, царем, і роби з ним, як тобі вгодно.","І сказав цар: нехай іде зі мною Кимгам, і я зроблю для нього, що тобі вгодно; і все, чого б не побажав ти від мене, я зроблю для тебе.","І перейшов весь народ Йордан, і цар також. І поцілував цар Верзеллія і благословив його, і він повернувся в місце своє.","І вирушив цар у Галгал, рушив з ним і Кимгам; і весь народ юдейський проводжав царя, і половина народу ізраїльського.","І ось, усі ізраїльтяни прийшли до царя і сказали цареві: навіщо брати наші, мужі Іудині, викрали тебе і провели царя і дім його і всіх людей Давида з ним через Йордан?","І відповіли всі мужі Іудині ізраїльтянам: тому, що цар ближній нам; і через що сердитися вам на це? Хіба ми що-небудь з’їли в царя, або одержали від нього подарунки? [Або від податків звільнив він нас?]","І відповіли ізраїльтяни мужам Іудиним і сказали: ми десять частин у царя, також і в Давида ми більше, ніж ви; [ми первісток, а не ви;] навіщо ж ви принизили нас? Чи не нам належало перше слово про те, щоб повернути нашого царя? Але слово мужів Іудиних було сильнішим, ніж слово ізраїльтян."],"x":{"4":"9.15.30","8":"9.5.1","12":"9.5.1","13":"9.17.25","16":"10.2.8","17":"9.9.2:10","21":"9.16.9|1.22.28","23":"10.2.8","24":"9.9.6","25":"9.16.3","27":"9.16.3","28":"9.9.11","29":"9.16.4","31":"9.17.27|10.2.7"}},{"v":["Там випадково знаходилася одна негідна людина, на ім’я Савей, син Бихри, веніамитянин; він засурмив трубою і сказав: немає нам частини у Давида, і немає нам частки у сині Ієссеєвому; усі по наметах своїх, ізраїльтяни!","І відокремилися всі ізраїльтяни від Давида і пішли за Савеєм, сином Бихри; юдеї ж залишилися на боці царя свого, від Йордану до Єрусалима.","І прийшов Давид у свій дім в Єрусалимі, і взяв цар десять дружин наложниць, яких він залишав стерегти дім, і помістив їх в особливий дім під нагляд, і утримував їх, але не ходив до них. І утримувалися вони там до дня смерти своєї, живучи як вдови.","І сказав Давид Амессаю: склич до мене юдеїв протягом трьох днів і сам з’явися сюди.","І пішов Амессай скликати юдеїв, але забарився більше призначеного йому часу.","Тоді Давид сказав Авессі: тепер наробить нам зла Савей, син Бихри, більше, ніж Авессалом; візьми ти слуг господаря твого і переслідуй його, щоб він не знайшов собі укріплених міст і не сховався від очей наших.","І вийшли за ним люди Іоавові, і хелефеї і фелефеї, і всі хоробрі пішли з Єрусалима переслідувати Савея, сина Бихри.","І коли вони були поблизу великого каменя, біля Гаваона, то зустрівся з ними Амессай. Іоав був одягнений у військовий одяг свій і оперезаний мечем, що висів при стегні в піхвах і який легко виходив з них і входив.","І сказав Іоав Амессаю: чи здоровий ти, брате мій? І взяв Іоав правою рукою Амессая за бороду, щоб поцілувати його.","Амессай же не остерігався меча, що був у руці Іоава, і той уразив його ним у живіт, так що випали нутрощі його на землю, і не повторив йому удару, і він помер. Іоав і Авесса, брат його, погналися за Савеєм, сином Бихри.","Один зі слуг Іоавових стояв над Амессаєм і говорив: той, хто відданий Іоаву і хто за Давида, нехай іде за Іоавом!","Амессай же [мертвий] лежав у крові серед дороги; і той чоловік, побачивши, що весь народ зупиняється над ним, стягнув Амессая з дороги в поле і накинув на нього одяг, оскільки він бачив, що кожен, хто минав, зупинявся над ним.","Але коли він був стягнутий з дороги, то весь народ ізраїльський пішов слідом за Іоавом переслідувати Савея, сина Бихри.","А він пройшов через усі коліна Ізраїльські до Авела-Беф-Мааха і через весь Берим; і [всі жителі міст] збиралися і йшли за ним.","І прийшли й обложили його в Авелі-Беф-Мааху; і насипали вал перед містом і підступили до стіни, і всі люди, які були з Іоавом, намагалися зруйнувати стіну.","Тоді одна розумна жінка закричала зі стіни міста: послухайте, послухайте, скажіть Іоаву, щоб він підійшов сюди, і я поговорю з ним.","І підійшов до неї Іоав, і сказала жінка: чи ти Іоав? І сказав: я. Вона сказала: послухай слів раби твоєї. І сказав він: слухаю.","Вона сказала: колись говорили: «хто хоче запитати, запитай в Авелі»; і так вирішували справу. [Чи залишилися такі, які вирішили бути вірними ізраїльтянами? Нехай запитають в Авелі: чи залишилися?]","Я з мирних, вірних міст Ізраїля; а ти хочеш знищити місто, і притому матір [міст] в Ізраїлі; для чого тобі руйнувати насліддя Господнє?","І відповів Іоав і сказав: нехай не буде цього від мене, щоб я знищив або зруйнував!","Це не так; але чоловік з гори Єфремової, на ім’я Савей, син Бихри, підняв руку свою на царя Давида; видайте мені його одного, і я відступлю від міста. І сказала жінка Іоаву: ось, голова його буде тобі кинута зі стіни.","І пішла жінка до всього народу зі своїм розумним словом [і говорила до всього міста, щоб відтяти голову Савею, синові Бихри]; і відтяли голову Савею, синові Бихри, і кинули Іоаву. Тоді [Іоав] засурмив трубою, і розійшлися від міста всі [люди] по своїх наметах; Іоав же повернувся в Єрусалим до царя.","І був Іоав поставлений над усім військом ізраїльським, а Ванея, син Іодаїв, — над хелефеями і над фелефеями;","Адорам — над збиранням податків; Іосафат, син Ахилуда, — діловодом;","Суса — писарем; Садок і Авиафар — священиками;","також і Іра іаритянин був священиком у Давида."],"x":{"1":"9.16.11|10.12.16","3":"9.16.21","4":"9.19.13","6":"9.18.2","7":"9.8.18|10.1.38","8":"5.10.41","9":"9.17.25","10":"9.3.27|10.2.5:32","12":"9.2.23","22":"26.24.21|30.7.7-8","23":"9.8.16:18","24":"10.4.3","25":"9.8.17"}},{"v":["Був голод на землі у дні Давида три роки, рік за роком. І запитав Давид Господа. І сказав Господь: це заради Саула і кровожерливого дому його, за те, що він умертвив гаваонитян.","Тоді цар покликав гаваонитян і говорив з ними. Гаваонитяни були не із синів Ізраїлевих, але із залишків аморреїв; ізраїльтяни ж дали їм клятву, але Саул хотів знищити їх через ревність свою за нащадків Ізраїля й Іуди.","І сказав Давид гаваонитянам: що мені зробити для вас, і чим примирити вас, щоб ви благословили насліддя Господнє?","І сказали йому гаваонитяни: не потрібно нам ні срібла, ні золота від Саула, або від дому його, і не потрібно нам, щоб умертвили когось в Ізраїлі. Він сказав: чого ж ви хочете? я зроблю для вас.","І сказали вони царю: того чоловіка, який губив нас і хотів знищити нас, щоб не було нас у жодному з наділів Ізраїлевих, —","з його нащадків видай нам сім чоловік, і ми повісимо їх [на сонці] перед Господом біля Гиви Саула, обраного Господом. І сказав цар: я видам.","Але пощадив цар Мемфивосфея, сина Іонафана, сина Саулового, заради клятви ім’ям Господнім, яка була між ними, між Давидом та Іонафаном, сином Сауловим.","І взяв цар двох синів Рицпи, дочки Айя, яка народила Саулу Армона і Мемфивосфея, і п’ять синів Мелхоли, дочки Саулової, яких вона народила Адриелу, синові Верзеллія з Мехоли,","і віддав їх у руки гаваонитян, і вони повісили їх [на сонці] на горі перед Господом. І загинули всі сім разом; вони умертвлені в перші дні жнив, на початку жнив ячменю.","Тоді Рицпа, дочка Айя, взяла ряднину і розстелила її для себе на тій горі і сиділа від початку жнив до того часу, поки не полилися на них води Божі з неба, і не допускала доторкатися до них птахам небесним вдень і звірам польовим уночі.","І донесли Давиду, що зробила Рицпа, дочка Айя, наложниця Саула. [І зотліли вони; і взяв їх Дан, син Іої, з нащадків велетнів.]","І пішов Давид і взяв кістки Саула і кістки Іонафана, сина його, у жителів Іависа галаадського, які таємно взяли їх із площі Беф-Сана, де вони були повішені филистимлянами, коли убили филистимляни Саула на Гелвуї.","І переніс він звідти кістки Саула і кістки Іонафана, сина його; і зібрали кістки повішених [на сонці].","І поховали кістки Саула та Іонафана, сина його, [і кістки повішених на сонці] у землі Веніаміновій, у Цела, у гробі Киса, батька його. І зробили все, що повелів цар, і змилостивився Бог над країною після того.","І почалася знову війна між филистимлянами й ізраїльтянами. І вийшов Давид і слуги його з ним, і воювали з филистимлянами; і Давид втомився.","Тоді Ієсвий, один з нащадків рефаїмів, у якого спис був вагою в триста сиклів міді і який був оперезаний новим мечем, хотів уразити Давида.","Але йому допоміг Авесса, син Саруїн, [і врятував Давида Авесса] і вразив филистимлянина й умертвив його. Тоді люди Давидові поклялися, говорячи: не вийдеш ти більше з нами на війну, щоб не погас світильник Ізраїля.","Потім була знову війна з филистимлянами в Гобі; тоді Совохай хушатянин убив Сафута, одного з нащадків рефаїмів.","Була й інша битва у Гобі; тоді убив Елханан, син Ягаре-Оргима вифлеємського, Голіафа гефянина, у якого ратище списа було, як навій у ткачів.","Була ще битва біля Гефи; і був там один чоловік високий на зріст, який мав по шість пальців на руках і на ногах, усього двадцять чотири, також з нащадків рефаїмів,","і він паплюжив ізраїльтян; але його убив Іонафан, син Сафая, брата Давидового.","Ці чотири були з роду рефаїмів у Гефі, і вони загинули від руки Давида і слуг його."],"x":{"1":"12.21.30|5.10.41","2":"5.9.19|5.11.19","6":"3.25.4|5.10.26|8.10.26","7":"8.20.16:42","8":"9.3.7|6.7.22","12":"8.31.10:12","14":"9.24.25","17":"9.4.7","18":"12.20.4","19":"8.17.7","20":"12.20.6","21":"9.13.3"}},{"v":["І заспівав Давид пісню Господу в день, коли Господь визволив його від руки усіх ворогів його і від руки Саула, і сказав:","Господь — твердиня моя і кріпкість моя і спаситель мій.","Бог мій — скеля моя; на Нього я уповаю; щит мій, ріг спасіння мого, огородження моє і притулок мій; Спасителю мій, від лих Ти визволив мене!","Закличу Господа всехвального і від ворогів моїх спасуся.","Обняли мене хвилі смерти, і потоки беззаконня устрашили мене;","кайдани пекла облягли мене, і сіті смерти обплутали мене.","Але в тісноті моїй я прикликав Господа і до Бога мого воззвав, і Він почув із [святого] чертога Свого голос мій, і волання моє дійшло до слуху Його.","Затряслася, захиталася земля, здригнулися і стряслися основи небес, бо розгнівався [на них Господь].","Піднявся дим від гніву Його і з вуст Його вогонь, що поїдає; розпечені вуглини сипалися від Нього.","Нахилив Він небеса і зійшов; і морок під ногами Його;","і возсів на херувимах, і полетів, і понісся на крилах вітру;","і мороком покрив Себе, як сінню, згустивши води хмар небесних;","від блискання перед Ним розпалювалися вуглини вогненні.","Загримів з небес Господь, і Всевишній дав глас Свій;","пустив стріли і розсіяв їх; [блиснув] блискавкою і знищив їх.","І відкрилися джерела моря, оголилися основи всесвіту від грізного гласу Господа, від подуву духу гніву Його.","Простер Він руку з висоти і взяв мене, і вивів мене з вод великих;","визволив мене від ворога мого сильного, від ненависників моїх, які були сильніші за мене.","Вони повстали на мене в день біди моєї; але Господь був опорою для мене","і вивів мене на просторе місце, визволив мене, бо Він благоволить до мене.","Воздав мені Господь за правдою моєю, за чистотою рук моїх нагородив мене.","Бо я зберігав путі Господа і не був нечестивим перед Богом моїм,","бо всі заповіді Його переді мною, і від уставів Його я не відступав,","і був непорочним перед Ним, і остерігався, щоб не згрішити мені.","І воздав мені Господь за правдою моєю, за чистотою моєю перед очима Його.","З милостивим Ти чиниш милостиво, з мужем щирим — щиро,","з чистим — чисто, а з лукавим — за лукавством його.","Людей пригноблених Ти спасаєш і поглядом Своїм принижуєш гордовитих.","Ти, Господи, світильник мій; Господь просвічує темряву мою.","З Тобою я вражаю військо; з Богом моїм піднімаюся на стіну.","Бог! — непорочна путь Його, чисте слово Господа, щит Він для всіх, які надіються на Нього.","Бо хто Бог, крім Господа, і хто захист, крім Бога нашого?","Бог підперезує мене силою, влаштовує мені вірну путь;","робить ноги мої, як оленячі, і на висотах поставляє мене;","навчає руки мої для битви і м’язи мої напружує, як мідний лук.","Ти даєш мені щит спасіння Твого, і милість Твоя звеличує мене.","Ти розширюєш крок мій піді мною, і не хитаються ноги мої.","Я ганяюся за ворогами моїми і знищую їх, і не повертаюся, доки не знищу їх;","і знищую їх і вражаю їх, і не встають і падають під ноги мої.","Ти підперезуєш мене силою для війни і знищуєш переді мною тих, хто повстає проти мене;","Ти повертаєш до мене тил ворогів моїх, і я знищую ненависників моїх.","Вони волають, але немає того, хто рятує, — до Господа, але Він не слухає їх.","Я розвіюю їх, як порох земний, як грязь вуличну мну їх і топчу їх.","Ти визволив мене від заколоту народу мого; Ти зберіг мене, щоб бути мені главою над іноплемінниками; народ, якого я не знав, служить мені.","Іноплемінники підлещуються переді мною; за чуткою про мене підкорюються мені.","Іноплемінники бліднуть і тремтять в укріпленнях своїх.","Живий Господь і благословенний захисник мій! Нехай буде звеличений Бог, пристановище спасіння мого,","Бог, Який мститься за мене і підкорює мені народи","і визволяє мене від ворогів моїх! Над тими, що повстають проти мене, Ти підняв мене; від людини жорстокої Ти визволив мене.","За те я буду славити Тебе, Господи, між іноплемінниками і буду співати імені Твоєму,","що велично спасаєш царя Свого і, твориш милість помазаникові Своєму Давиду і потомству його повіки!"],"x":{"2":"25.17.3","3":"9.23.3|0.15.1|25.7.2","6":"24.22.10|26.14.27|25.17.6","8":"25.17.8","9":"1.24.17|4.4.24","12":"24.36.28|31.50.3","14":"25.28.3","15":"8.2.10","17":"24.22.11|25.31.6|31.43.2","20":"25.30.9","21":"24.22.30|25.4.2","25":"25.7.10","28":"26.29.23|30.20.11|24.22.29","29":"25.26.1|25.111.4|24.29.3","32":"1.15.11|31.43.11","35":"0.49.8|4.33.29","36":"25.3.4","39":"25.26.2","41":"0.49.8","43":"25.82.11|31.10.6|32.8.2","44":"9.8.6|25.59.10","47":"4.32.40|25.41.3|36.14.16","50":"62.15.9","51":"9.8.6|65.3.16"}},{"v":["Ось останні слова Давида, висловлювання Давида, сина Ієссеєвого, висловлювання мужа, поставленого високо, помазаника Бога Якова і солодкого співака Ізраїлевого:","Дух Господній говорить у мені, і слово Його на язиці моєму.","Сказав Бог Ізраїлів, говорила про мене скеля Ізраїлева: той, хто володарює над людьми, буде праведний, володарюючи в страху Божому.","І як на світанку ранковому, при сході сонця на безхмарному небі, від сяйва після дощу виростає трава з землі,","чи не так дім мій у Бога? Бо завіт вічний уклав Він зі мною, міцний і непорушний. Чи не так виходить від Нього все спасіння моє і все бажання моє?","А нечестиві будуть, як викинуте терня, яке не беруть рукою;","але хто торкається його, озброюється залізом або деревом списа, і вогнем спалює його на місці.","Ось імена хоробрих у Давида: Ісбосеф ахаманитянин, головний із трьох; він підняв спис свій на вісімсот чоловік і вразив їх в один раз.","За ним Єлеазар, син Додо, сина Ахохи, із трьох хоробрих, які були з Давидом, коли вони осудженням викликали филистимлян, які зібралися на війну;","ізраїльтяни вийшли проти них, і він став і вражав филистимлян до того, що рука його стомилася і прилипла до меча. І дарував Господь у той день велику перемогу, і народ пішов за ним тільки для того, щоб оббирати вбитих.","За ним Шамма, син Аги, гараритянин. Коли филистимляни зібралися у Фириї, де було поле, засіяне сочевицею, і народ побіг від филистимлян,","то він став серед поля і зберіг його і вразив филистимлян. І дарував тоді Господь велику перемогу.","Троє цих головних із тридцяти вождів пішли і ввійшли під час жнив до Давида в печеру Одоллам, коли юрби филистимлян стояли в долині рефаїмів.","Давид був тоді в укріпленому місці, а загін филистимлян — у Вифлеємі.","І захотів Давид пити, і сказав: хто напоїть мене водою з колодязя Вифлеємського, що біля воріт?","Тоді троє цих хоробрих пробилися крізь стан филистимський і почерпнули води з колодязя Вифлеємського, що біля воріт, і взяли і принесли Давиду. Але він не захотів пити її і вилив її у славу Господа,","і сказав: збережи мене Господи, щоб я зробив це! чи не кров це людей, які ходили з небезпекою для власного життя? І не захотів пити її. Ось що зробили ці троє хоробрих!","І Авесса, брат Іоава, син Саруїн, був головним із трьох; він убив списом своїм триста чоловік і був у славі у тих трьох.","Із трьох він був найзнатнішим і був начальником, але з тими трьома не рівнявся.","Ванея, син Іодая, чоловіка хороброго, великий за ділами, з Кавцеїла; він уразив двох синів Ариїла моавитського; він же спустився й убив лева у рові в сніжний час;","він же убив одного єгиптянина, людину поважну; у руці єгиптянина був спис, а він пішов до нього з палкою і відняв спис з руки єгиптянина, й убив його власним його списом:","ось що зробив Ванея, син Іодаїв, і він був у славі у трьох хоробрих;","він був знатнішим тридцяти, але з тими трьома не рівнявся. І поставив його Давид найближчим виконавцем своїх наказів.","[Ось імена сильних царя Давида:] Асаїл, брат Іова, — у числі тридцяти; Елханан, син Додо, з Вифлеєма,","Шамма хародитянин, Елика хародитянин,","Херец палтитянин, Іра, син Ікеша, фекоїтянин,","Евиезер анафофянин, Мебуннай хушатянин,","Цалмон ахохитянин, Магарай нетофафянин,","Хелев, син Баани, нетофафянин, Іттай, син Рибая, з Гиви синів Веніамінових,","Ванея пирафонянин, Іддай з Нахле-Гааша,","Ави-Албон арбатитянин, Азмавет бархюмитянин,","Елияхба шаалбонянин; із синів Яшена — Іонафан,","Шама гараритянин, Ахиам, син Шарара, араритянин,","Елифелет, син Ахасбая, сина Магахати, Елиам, син Ахитофела, гилонянин,","Хецрай кармилитянин, Паарай арбитянин,","Ігал, син Нафана, з Цоби, Бані гадитянин,","Целек аммонитянин, Нахарай беротянин, зброєносець Іоава, сина Саруї,","Іра ітритянин, Гареб ітритянин,","Урія хеттеянин. Усіх тридцять сім."],"x":{"1":"9.7.12|68.3.16","2":"54.1.16|51.12.36","3":"1.17.5","4":"53.1.4|25.109.3|26.4.18","5":"9.7.15-16","6":"25.57.10|75.6.8","7":"31.1.31","8":"12.11.11","9":"12.11.12","10":"8.11.13","13":"12.11.15","14":"12.11.16","15":"12.11.17","17":"12.11.19","18":"12.11.20|9.21.17","20":"12.11.22|5.15.21","24":"12.11.26-27","29":"12.27.15","30":"12.11.31"}},{"v":["Гнів Господній знову запалав на ізраїльтян, і побудив він проти них Давида сказати: піди, порахуй Ізраїля й Іуду.","І сказав цар Іоаву воєначальникові, який був при ньому: пройди по всіх колінах Ізраїлевих [і Іудиних] від Дана до Вирсавії, і порахуй народ, щоб знати мені кількість народу.","І сказав Іоав царю: Господь Бог твій нехай примножить стільки народу, скільки є, і ще у сто разів стільки, а очі господаря мого царя нехай побачать це; але для чого господар мій цар бажає цієї справи?","Але слово царя до Іоава і воєначальників перемогло; і пішов Іоав з воєначальниками від царя рахувати народ ізраїльський.","І перейшли вони Йордан і зупинилися в Ароері, на правому боці міста, що серед долини Гадової, до Іазера;","і прийшли в Галаад і в землю Тахтим-Ходши; і прийшли в Дан-Яан і обійшли Сидон;","і прийшли до укріплення Тира і в усі міста хивеян і хананеян і вийшли на південь Юдеї у Вирсавію;","і обійшли всю землю і прийшли через дев’ять місяців і двадцять днів у Єрусалим.","І подав Іоав список народного перепису царю; і виявилося, що ізраїльтян було вісімсот тисяч чоловіків сильних, здатних до війни, а юдеян п’ятсот тисяч.","І здригнулося серце Давидове після того, як він порахував народ. І сказав Давид Господу: тяжко згрішив я, вчинивши так; і нині молю Тебе, Господи, прости гріх раба Твого, бо вкрай нерозумно зробив я.","Коли Давид устав на другий день ранком, то було слово Господа до Гада пророка, прозорливця Давида:","піди і скажи Давиду: так говорить Господь: три покарання пропоную Я тобі; вибери собі одне з них, яке звершилося б над тобою.","І прийшов Гад до Давида, і сповістив йому, і сказав йому: обирай собі, чи бути голоду в країні твоїй сім років, чи щоб ти три місяці бігав від ворогів твоїх, і вони переслідували тебе, чи щоб упродовж трьох днів була моровиця в країні твоїй? тепер розсуди і виріши, що мені відповісти Тому, Хто послав мене.","І сказав Давид Гадові: тяжко мені дуже; але нехай упаду я в руки Господа, бо велике милосердя Його; тільки б у руки людські не впасти мені. [І обрав собі Давид моровицю під час жнив пшениці.]","І послав Господь моровицю на ізраїльтян від ранку до призначеного часу; [і почалася моровиця в народі] і померло з народу, від Дана до Вирсавії, сімдесят тисяч чоловік.","І простяг ангел [Божий] руку свою на Єрусалим, щоб спустошити його; але Господь пожалів про біду і сказав ангелові, який уражав народ: досить, тепер опусти руку твою. Ангел же Господній був тоді біля току Орни ієвусеянина.","І сказав Давид Господу, коли побачив ангела, який уражав народ, говорячи: ось, я згрішив, я [пастир] вчинив беззаконно; а ці вівці, що зробили вони? нехай же рука Твоя обернеться на мене і на дім батька мого.","І прийшов у той день Гад до Давида і сказав: іди, постав жертовник Господу на току Орни ієвусеянина.","І пішов Давид за словом Гада [пророка], як повелів Господь.","І глянув Орна і побачив царя і слуг його, які йшли до нього, і вийшов Орна й уклонився цареві лицем своїм до землі.","І сказав Орна: навіщо прийшов господар мій цар до раба свого? І сказав Давид: купити в тебе тік для спорудження жертовника Господу, щоб припинилось ураження народу.","І сказав Орна Давиду: нехай візьме і принесе в жертву, господар мій, цар, що йому вгодно. Ось воли для всепалення і вози й упряж волова на дрова.","Все це, царю, Орна віддає цареві. Ще сказав Орна царю: Господь Бог твій нехай буде милостивим до тебе!","Але цар сказав Орні: ні, я заплачу́ тобі, що коштує, і не принесу Господу Богу моєму жертви, взятої задарма. І купив Давид тік і волів за п’ятдесят сиклів срібла.","І спорудив там Давид жертовник Господу і приніс всепалення і мирні жертви. [Потім Соломон розширив жертовник, бо він був малий.] І змилостивився Господь над країною, і припинилось ураження ізраїльтян."],"x":{"1":"12.21.1","4":"12.21.4","5":"4.2.36|5.13.16","9":"12.21.5","10":"12.21.8","11":"12.21.9","13":"12.21.11-12","14":"30.2.18","16":"32.42.10","17":"12.21.17","18":"12.21.18|13.3.1","22":"12.21.23|10.19.21","25":"0.12.7|9.21.14|12.21.26"}}];
